</pre><b>Architecture of c program</b>
Function consists of header and body
 - Header contains preprocessor statements and class declarations (except template
inclusion case where source is also included)
 - Body, enclosed in {brackets} contains statements, each terminated by semicolon

One function must be one called main()
 - C start up code calls main function as the entry point in the program.

Global variables are initialized prior the entry to main function.

Program execution starts in main, and progresses, statement by statement, until the
last statement in main is completed

Definition of variable class and functions put in source file.
A source file contains definition of variable and functions.

&lt;&lt;source.c&gt;&gt;
<pre class="code">extern int i; // declaration
int func(); // declaration
int i=10;//declaration and definition
int func(){//definition
}
</pre>
Compiling one source file needs only declarations of the variable and the function be
visible. Definition is not required while generating object file.

<pre class="code">$ cat source.c
#include &lt;stdio.h&gt;

int func();
int main(){
func();
return 0;
</pre></pre>
