<pre class="slidecontent">

Header contains constants, macros, system wide global variables, preprocessor
statements and declarations.

Header file is included with #include
example

<pre class="code">$ cat header.h
#ifndef HEADER_H
#define HEADER_H
#include &lt;stdio.h&gt;
const int i=10;
extern int j;
struct A{
};
void put_s(const char*);
#endif

$cat source1.c
#include "header.h"
void put_s(const char *cp){
printf("puts %s
",cp);
}

$cat source2.c
#include "header.h"
int j=15;

$cat main.c
#include "header.h"
int main(int argc, char *argv[]){
puts("hello world");
printf("j %d
",j);
return 0;
}

$ g++ source1.c source2.c main.c -o headersource
$ ./headersource 
hello world
j 15    
</pre>
