A file that contains compiled code is known as an object file. Compiler creates object
file which is binary file.  It is of three types

a) Relocatable file
This type of object file contains data and code that can be linked together with other
relocatable files to produce an executable binary or a shared object file. It is
similar as the .o file produced when we compile a code the following way :
</pre>
