<pre class="code">$ cat mathoperation.c

void fixit(int,int);
int add(int a,int b){
return a+b;
}
int mul(int a,int b){
return a*b;
}
int div(int a,int b){
if (b=0)fixit(a,b);
return a/b;
}
</pre>
b) Shared object file
This type of object file is used by the dynamic linker to combine it with the
executable and/or other shared object. It is similar as the .so file produced when the
code is compiled with the -fPIC (position independent code) flag in the following way
:

<pre class="code">$gcc -c -Wall -Werror -fPIC shared.c -o shared.o
$gcc -shared -o libshared.so shared.o
</pre> 
A shared object file libshared.so is produced as output.

example.
<pre class="code">$gcc -c -fPIC mathoperation.c -o mathoperation.o

$ nm mathoperation.o
0000000000000000 T add
