c) Executable file
This type of object file is a file that is capable of executing a program when run.

<pre class="code">$ gcc -Wall test.c -o test
</pre>Tool - objdump, nm
 
Example -
&lt;&lt;main.c&gt;&gt;
<pre class="code">#include "sample.h"
int main(int argc, char *argv[]){
struct fraction frtn;
frtn.numerator=12;
frtn.denominator=5;
func(&amp;frtn);
return 0;
}
</pre>
&lt;&lt;sample.c&gt;&gt;
<pre class="code">#include &lt;stdio.h&gt;
#include "sample.h"
void func(struct fraction *f){
printf("value %d
",f-&gt;numerator/f-&gt;denominator);
}
</pre>
&lt;&lt;sample.h&gt;&gt;
<pre class="code">#ifndef SAMPLE_H
#define SAMPLE_H
struct fraction {
int numerator;
int denominator;
};
void func(struct fraction *f);
#endif
</pre>
