Preprocessor - It is a program that runs as part of compilation of a c program.  It is
</pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main1" class="pn">p13</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
not part of compiler. In simplistic terms, a C Preprocessor is just a text
substitution tool and they instruct compiler to do required preprocessing before
actual compilation.
All preprocessor commands begin with a pound symbol (#). It must be the first non
blank character, and for readability, a preprocessor directive should begin in first
column. Following section lists down all important preprocessor directives:

<pre class="code">Directive              Description
#define                Substitutes a preprocessor macro
#include               Inserts a particular header from another file
#undef                 Undefines a preprocessor macro
#ifdef                 Returns true if this macro is defined
#ifndef                Returns true if this macro is not defined
#if                    Tests if a compile time condition is true
#else                  The alternative for #if
#elif                   #else an #if in one statement
#endif                 Ends preprocessor conditional
#error                 Prints error message on stderr
#pragma                Issues special commands to the compiler, using
</pre>

Tool - cpp

$ cat test.h
<pre class="code">#ifndef TEST_H
#define TEST_H
int func():
#endif
$ cat test.cpp
#include "test.h"
int main(){
return 0;
}
</pre>
$ cpp test.cpp
<pre class="code"># 1 "test.cpp"
# 1 "&lt;command-line&gt;"
# 1 "/usr/include/stdc-predef.h" 1 3 4
# 1 "&lt;command-line&gt;" 2
# 1 "test.cpp"
# 1 "test.h" 1

int func():
# 2 "test.cpp" 2
int main(){
return 0;
}
</pre>
Compiling Source Files
Once your program is written in C, it is ready to be translated into a 
machine-readable language.
A compiler translates C statements into machine statements
- A compiler creates object code, which is an intermediary step between source code
and final executable code
- The compiler checks for syntax errors; e.g., Missing punctuation
- The compiler performs simple optimization on your code; e.g., eliminate a redundant
statement

Tool - gcc

Linking Object Files
- The linker links together all object modules to form an executable image of the
program
- The output of the linker is an executable image, which can be loaded into memory and
executed
- The linker resolves any references to library functions
 - If your program uses a library routine, like sqrt, the linker finds the object code
corresponding to this routine and links it within the final executable image
- The linker is automatically invoked by the compiler

Loading Your Program
The loader loads your program into the computer's memory
On most systems, this is performed automatically by the operating system 
when you run the program
Most embedded systems require you to explicitly run a loader program
to get the program into memory

</pre>
