<pre class="slidecontent">

Unix/Linux process virtual address space

<pre class="code">high address -----------------------------
             |                           |    command line arguments
             |                           |  /  and environment
             -----------------------------
             |           stack           |
             - - - - - - - - - - - - - - -
             |             |             |
             |             |             |
             |             v             |
             |                           |
             |                           |
             |                           |
             |             ^             |
             |             |             |
             |             |             |
             - - - - - - - - - - - - - - -
             |           heap            |
             -----------------------------
             | uninitialized data        |  initialized to
             |          (bss)            | / zero by exec
             ----------------------------+ 
             | initialized data          |   read from
             -----------------------------   | program line
             |            text           |  / by exec
low address  |                           | /
             +---------------------------+
</pre>                                                                                      
        
When an executable program is read into system memory by the kernel and executed, it
becomes a process. We can consider system memory to be divided into two distinct
regions.

One is user space, and the other is kernel Space. Every process has is own user space
(about 2GB virtual space,32bit) and are prevented from interfering with one another.
The mode change which is from user mode to kernel mode is called a context switch.

<pre class="code">         -----------------
         |  Kernel Space |&lt;----+
         |               |     |
         +---------------+     | context switching
         |               |     |
         | User Space    |&lt;----+
         +---------------+
</pre>
Text, Data and Stack.
The user process is divided into three segments or regions, they are: text, data and
stack.

Text Segment.
The Text segment (a.k.a the Instruction segment) contains the executable program code
and constant data. The text segment is marked by the operating system as read- only
and can not be modified by the process.  Multiple processes can share the same text
segment. Processes share the text segment if a second copy of the program is to be
executed concurrently. Sharing can be turned off by using the -N option on the compile
time.

Data Segment.
The data segment, which is contiguous (in a virtual sense) with the text segment, can
be subdivided into initialized data (e.g. in C/C++, variables that are declared as
static or are static by virtual of their placement) and uninitialized (or
0-initialized data. The uninitialized data area is also called BSS (Block Started By
Symbol).
</pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main1" class="pn">p17</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">

Heap Segment
During its execution lifetime, a process may request additional data segment space.
Library memory allocation routines (e.g., new, malloc, calloc, etc.) in turn make use
of the system calls brk and sbrk to extend the size of the data segment. The newly
allocated space is added to the end of the current uninitialized data area. This area
of available memory is also called "heap".                                      

Stack Segment.
The stack segment is used by the process for the storage of automatic identifier,
register variables, and function call information. The stack grows towards the
uninitialized data segment.

The u area.
In addition to the text, data, and stack segment, the OS also maintains for each
process a region called the u area (User Area). The u area contains information
specific to the process (e.g. open files, current directory, signal action, accounting
information) and a system stack segment for process use.  If the process makes a
system call (e.g., the system call to write in the function in main ), the stack frame
information for the system is stored in the system stack segment. Again, this
information is kept by the OS in an area that the process doesn't normally have access
to. Thus, if this information is needed, the process must use special system call to
access it.  Like the process itself, the contents of the u area for the process are
paged in and out bye the OS.

Process Memory Addresses.
The system keeps track of the virtual addresses associated with each user process
segment. This addresses information is available to the process and can be obtained by
referencing the external variables etext, edata, and end. The addresses (not the
contents) of these three variable correspond respectively to the first valid address
above the text, initialized data, and uninitialized data segments.

<pre class="code">#include &lt;iostream&gt;
extern int etext, edata, end;
using namespace std;
int main( ){
cout &lt;&lt; "Adr etext: " &lt;&lt; hex &lt;&lt; &amp;etext &lt;&lt; "	 ";
cout &lt;&lt; "Adr edata: " &lt;&lt; hex &lt;&lt; &amp;edata &lt;&lt; "	 ";
cout &lt;&lt; "Adr end: " &lt;&lt; hex &lt;&lt; &amp;end &lt;&lt; "
";

char *s1 = "hello"; //in initialized data segmenta
static int a=1; //in initialized data segment
static int b; //in uninitialized data segment
char s2[] = "hello"; //in the stack area.
int * c = new int;

cout &lt;&lt;hex &lt;&lt; s1 &lt;&lt; endl;
cout &lt;&lt;hex &lt;&lt; &amp;a &lt;&lt; endl;
cout &lt;&lt;hex &lt;&lt; &amp;b &lt;&lt; endl;
cout &lt;&lt;hex &lt;&lt; s2 &lt;&lt; endl;
cout &lt;&lt;hex &lt;&lt; c &lt;&lt; endl;
delete c;
return 0;
}
</pre>
