<pre class="slidecontent">

A static library is set of object files that were copied into a single file. The
static file is created with the archiver (ar).

&lt;&lt;calc_mean.c&gt;&gt;
<pre class="code">//#include &lt;stdio.h&gt;
double mean(double a, double b) {
return (a+b) / 2;
}
</pre>
&lt;&lt;calc_mean.h&gt;&gt;
<pre class="code">double mean(double, double);
</pre>
Creating the static library
First, calc_mean.c is turned into an object file:

<pre class="code">$gcc -c calc_mean.c -o calc_mean.o
</pre>
Then, the archiver (ar) is invoked to produce a static library (named libmean.a) out
of the object file calc_mean.o.

<pre class="code">$ar  rcs libmean.a      calc_mean.o
</pre>
Note: the library must start with the three letters lib and have the suffix .a.

$cat calc.c
<pre class="code">#include &lt;stdio.h&gt;
#include "calc_mean.h"
int main(){
printf ("mean of 3, 6 is %f 
",mean(3,6));
return 0;
}
</pre>
$ gcc -c calc_mean.c -o calc_mean.o
$ ar cr libmean.a calc_mean.o
$ gcc -c calc.c -o calc.o
$ gcc -o calc calc.o -L. -lmean
$ ./calc 
<pre class="code">
mean of 3, 6 is 4.500000 
</pre>
$ gcc -o calc  -L. -lmean calc.o
<pre class="code">calc.o: In function 'main':
calc.c:(.text+0x2f): undefined reference to 'mean'
collect2: error: ld returned 1 exit status
</pre>
$ nm libmean.a 
<pre class="code">calc_mean.o:
0000000000000000 T mean
</pre>
