Shared library (also known as a shared object, or as a dynamically linked library) is
similar to a archive in that it is a grouping of object files.  When a shared library
is linked into a program, the final executable does not actually contain the code that
is present in the shared library. Instead, the executable merely contains a reference
to the shared library.

The program using the library
&lt;&lt;main.c&gt;&gt;
<pre class="code">#include &lt;stdio.h&gt;
#include "calc_mean.h"
int main(){
printf ("mean of 3, 6 is %f 
",mean(3,6));
return 0;
}
</pre>
$ gcc -c -fPIC calc_mean.c -o calc_mean.o
$ gcc -c calc.c -o calc.o
$ gcc -shared -fPIC -o libmean.so calc_mean.o
$ ldd libmean.so

<pre class="code">linux-vdso.so.1 =&gt;  (0x00007fffadffe000)
libc.so.6 =&gt; /lib64/libc.so.6 (0x00007f546f7ed000)
/lib64/ld-linux-x86-64.so.2 (0x00007f546fdc4000)
</pre>
$ gcc -o calc calc.o -L. -lmean
$ ldd calc

<pre class="code">linux-vdso.so.1 =&gt;  (0x00007fffa58de000)
libmean.so =&gt; not found
libc.so.6 =&gt; /lib64/libc.so.6 (0x00007f4e10d70000)
/lib64/ld-linux-x86-64.so.2 (0x00007f4e11146000)
</pre>
$ export LD_LIBRARY_PATH=.
$ ./calc 

mean of 3, 6 is 4.500000 
In order to avoid LD_LIBRARY_PATH programmer can add 
-Wl,rpath,&lt;lib path&gt; to the command link line

