<pre class="slidecontent">

A calling convention describes how the arguments are passed and values returned by
functions. 

It also specifies how the function names are decorated.


1) C calling convention (__cdecl)
<pre class="code">int __cdecl sumExample (int a, int b);
</pre>
- Arguments are passed from right to left, and placed on the stack.
- Stack cleanup is performed by the caller.
- Function name is decorated by prefixing it with an underscore character '_' .
- The default calling convention for C and C++ programs. The advantage of this calling
convention is that it allows functions with a variable number of arguments to be used.
The disadvantage is that it creates larger executable.

2) Standard calling convention (__stdcall)
<pre class="code">int __stdcall sumExample (int a, int b);
</pre>
- Arguments are passed from right to left, and placed on the stack.
- Stack cleanup is performed by the called function.
- Function name is decorated by prepending an underscore character and appending a '@'
character and the number of bytes of stack space required.
- It is used to call Win32 API functions. It does not allow functions to have a
variable number of arguments.

3) Fast calling convention (__fastcall)
<pre class="code">int __fastcall sumExample (int a, int b);
</pre>
- The first two function arguments that require 32 bits or less are placed into
registers ECX and EDX. The rest of them are pushed on the stack from right to left.
- Arguments are popped from the stack by the called function.
- Function name is decorated by by prepending a '@' character and appending a '@' and
the number of bytes (decimal) of space required by the arguments.
- __fastcall attempts to put arguments in registers, rather than on the stack, thus
making function calls faster.
   

4) Thiscall
- Arguments are passed from right to left, and placed on the stack. this is placed in
ECX. Stack cleanup is performed by the called function.
- Thiscall calling convention is the default calling convention used by C++ member
functions that do not use variable arguments.

</pre> &nbsp;<div class="slideheader" style="height:205px">
