<pre class="slidecontent">

Name mangling is changing function names to avoid name conflict. Used in function
overloading.

<pre class="code"></pre></pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main1" class="pn">p21</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
<pre class="code">void fun(int x) {
    cout&lt;&lt;x&lt;&lt;endl;
}
void fun(float x) {
    cout&lt;&lt;x&lt;&lt;endl;
}
int main() {
    fun(10);
    fun(10.5f);

    return 0;
}
</pre>
Mangled name for funtion void fun(int x) is <pre class="code" style="display:inline">?fun@@YAXH@Z</pre>
Mangled name for funtion void fun(float x) is <pre class="code" style="display:inline">?fun@@YAXM@Z</pre>

Tool - nm

<pre class="code">#ifndef SAMPLE_H
#define SAMPLE_H
#include &lt;iostream&gt;
using namespace std;
struct fraction {
int numerator;
int denominator;
};
class cfraction{
int numerator;
int denominator;
public:
cfraction(int,int);
void func();
};
#endif

#include "sample.h"
cfraction::cfraction(int n,int d){
numerator=n;
denominator=d;
}
void cfraction::func(){
cout&lt;&lt;numerator/denominator;
}
</pre>
