<pre class="slidecontent">

The stack frame, also known as activation record is the collection of all data on the
stack associated with one subprogram call.
The stack frame generally includes the following components:

- The return address
- Argument variables passed on the stack
- Local variables (in HLLs)
- Saved copies of any registers modified by the subprogram that need to be restored
(e.g. $s0 - $s8 in MAL). 

Automatic variables are therefore represented as an offset from the stack pointer,
such as 4($sp) or 8($sp).

<pre class="code">int     function(int a, double b)
{
 int     x, y;
 ...
 return  x;
}
</pre>
Possible stack frame for function:
Address Content
<pre class="code">$sp --&gt; F080    Saved return address
        F084    a
        F088    b
        F090    x
        F094    y
        F098    Saved register value
        F09C    Saved register value
</pre>
Function can return object(value) or reference. Do not return reference or pointer to
local variable, as function de-allocate stack once it returns.  
Return type of overloaded function does not contribute to overloading.

