<pre class="slidecontent">

- If a function is inline, the compiler places a copy of the code of that function at
each point where the function is called at compile time.
- Any change to an inline function could require all clients of the function to be
</pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main2" class="pn">p25</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
recompiled.
- To inline a function, place the keyword inline before the function name and define
the function before any calls are made to the function.
- The compiler can ignore the inline qualifier in case defined function is more than a
line.
- An inline function does type check and it is not MACRO.

Automatic In-lining
- A function definition in a class definition is an inline function definition, even
without the use of the inline specifier.
- Inline function definition must be in header files.

<pre class="code">#include &lt;iostream&gt;
using namespace std;
inline void func(){ // non class function inline
cout&lt;&lt;"global inline func"&lt;&lt;endl;
}
class classA {
public:
inline const string&amp; shorterstring(const string &amp;s1, const string &amp;s2); //inline
void uppercase(const string&amp; s);
};
const string&amp; classA::shorterstring(const string &amp;s1, const string &amp;s2){
return s1.size() &lt; s2.size() ? s1:s2;
}
inline void classA::uppercase(const string&amp; s){
s.toUpperCase();
}
int main() {
classA clsA;
cout&lt;&lt;clsA.shorterstring("one","three")&lt;&lt;endl;
func();
return 0;
}
</pre>
