<pre class="slidecontent">

- Multiple definitions for the same function name in the  same scope.  The definition
of the function must differ from each other by the types and/or the number of
arguments in the argument list.
- Can not overload function declarations that differ only by return type.

<pre class="code">void print(int i) {
cout &lt;&lt; "Printing int: " &lt;&lt; i &lt;&lt; endl;
}
void print(double f) {
cout &lt;&lt; "Printing float: " &lt;&lt; f &lt;&lt; endl;
}
//void print(long double l) {
//cout&lt;&lt;"Printing long:"&lt;&lt;l&lt;&lt;endl;
//}
void print(char* c) {
cout &lt;&lt; "Printing character: " &lt;&lt; c &lt;&lt; endl;
}
int main(int argc, char *argv[]) {
int i=10;
double d=20.10;
long double ld=10.10001;
char *cp="ORACLE";
print(i);
print(d);
print(ld);
print(cp);
return 0;
}
</pre>
Overloading and ambiguity
- There can be ambiguity when exact matching type is not available and intermediate
conversion is required where target type is more than one..
- If both functions are available that is without the overloaded argument and with
overloaded argument but with default values.

In order to overcome ambiguity look the following rule is followed
a) Select candidates. Same function name.
b) Select viable function. Select function which has equal number of matching
arguments.
c) Select best match function. Function that require minimum conversion.

<pre class="code">#include &lt;iostream&gt;
#include &lt;string&gt;
using namespace std;

void print(int i){cout&lt;&lt;"print int"&lt;&lt;endl;}
void print(float f){cout&lt;&lt;"print float"&lt;&lt;endl;}
void print(char c){cout&lt;&lt;"print char"&lt;&lt;endl;}
void print(double d){cout&lt;&lt;"print double"&lt;&lt;endl;}
void print(int *i){cout&lt;&lt;"print int*"&lt;&lt;endl;}
class complex{
public:
complex(double){}
};

class longdouble{
friend double operator+(longdouble&amp;, int);
//friend double operator+(longdouble&amp;, double);
public:
longdouble(int){};
operator double(){return 4.4;}
double operator+(const complex&amp;){
cout&lt;&lt;"::operator+complex"&lt;&lt;endl;
}
};
double operator+(longdouble&amp; l, int i){
//double operator+(longdouble&amp; l, double i){
cout&lt;&lt;"global operator+"&lt;&lt;endl;
}
int main(){
</pre></pre>
