<pre class="slidecontent">

- When a function is defined, a default value can be specified for each of the last
parameters.
- This value will be used if the corresponding argument is left blank when calling to
the function.
- This is done by using the assignment operator and assigning values for  the
arguments in the function definition. If a value for that parameter  is not passed
when the function is called, the default given value is used, but if a value is
specified, this default value is ignored and the passed value is used instead.

<pre class="code">#include &lt;iostream&gt;
using namespace std;
int sum(int a, int b=20) {
int result;
result = a + b;
return (result);
}

int sum(int a, int b){//error multiple definition
Return a+b;
}

int main () {
int a = 100;
int b = 200;
int result;
result = sum(a, b);
cout &lt;&lt; "Total value is :" &lt;&lt; result &lt;&lt; endl;
result = sum(a);
cout &lt;&lt; "Total value is :" &lt;&lt; result &lt;&lt; endl;
return 0;
}
</pre>
