<pre class="slidecontent">

Two way parameter to function can be passed
- By value
- By reference

</pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main2" class="pn">p28</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
By value
Value is of the argument passed by callee the function is exactly copied in the caller
parameter variable.

<pre class="code">void swap(int *v1, int *v2){
int tmp=*v2;
*v2=*v1;
*v1=tmp;
}
void swapptr(int **v1, int **v2){
int *tmp=*v2;
*v2=*v1;
*v1=tmp;
}

By reference
void swap(int &amp;v1,int &amp;v2){
int tmp=v2;
v2=v1;
v1=tmp;
}
void swapptr( int *&amp;v1,int *&amp;v2){
int *tmp=v2;
v2=v1;
v1=tmp;
}
</pre>
Array Value
<pre class="code">void printvalue(int arr[10]);
void printvalue(int *arr);
void printvalue(int arr[]);
</pre>
Reference
<pre class="code">void printvalue(int (&amp;arr)[10]);
void printvalue(int (&amp;arr)[10][10]);

#include &lt;iostream&gt;
using namespace std;

void printptrtoarray(int (*arr)[4]){
int i=0,j=0;
for(i=0;i&lt;4;i++){
for(j=0;j&lt;4;j++)
cout&lt;&lt;arr[i][j]&lt;&lt;" ";
cout&lt;&lt;endl;
}
}
void printarray(int (&amp;arr)[4][4]){
int i=0,j=0;
for (i=0;i&lt;4;i++){
for (j=0;j&lt;4;j++)
cout&lt;&lt;arr[i][j]&lt;&lt;" ";
cout&lt;&lt;endl;
}
}
void preparearray(int (&amp;arr)[4][4]){
int i=0,j=0;
for (i=0;i&lt;4;i++)
for (j=0;j&lt;4;j++)
arr[i][j]=i;
}
int main(int argc,char *argv[]){
int arr[4][4];
preparearray(arr);
printarray(arr);
printptrtoarray(arr);
return 0;
}
