<pre class="slidecontent">

Unnamed function parameters are used when a particular parameter is not required but
it is in design.

<pre class="code">                       A
                 +------------+
                 | func()=0;  |
                 +------------+
                       / 
                        -
                        |
    +----------------------------------+
  B |                                C |
+-------------+                 +--------------+
|   func()    |                 |    func()    |
+-------------+                 +--------------+


#include &lt;iostream&gt;
using namespace std;
struct A{
virtual void func(int *)=0;
};
struct B:A{
virtual void func(int *);
};
struct C:A{
virtual void func(int*);
};
void B::func(int *){
cout&lt;&lt;"A::func"&lt;&lt;endl;
}
void C::func(int *i){
cout&lt;&lt;"B::func"&lt;&lt;*i&lt;&lt;endl;
}
void callfunc(A* a){
int i=10;
a-&gt;func(&amp;i);
}

int main(int argc, char *argv[]){
B b;
C c;
callfunc(&amp;b);
callfunc(&amp;c);
return 0;
}
</pre>$ ./a.out 
<pre class="code">A::func
B::func10
</pre>
