<pre class="code">#include &lt;stdarg.h&gt; 
double average(int num,...) 
{ 
va_list valist; 
double sum = 0.0; 
int i; 
/* initialize valist for num number of arguments */ 
va_start(valist, num); 
</pre></pre>
