<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
<pre class="code">


/* access all the arguments assigned to valist */ 
for (i = 0; i &lt; num; i++)  { 
sum += va_arg(valist, int); 
} 
/* clean memory reserved for valist */ 
va_end(valist); 
return sum/num; 
} 
</pre>
- Define a function with last parameter as ellipses and the one just before  the
ellipses is always an int which will represent number of arguments. 
- Create a va_list type variable in the function definition. This type is  defined in
stdarg.h header file. 

-Use int parameter and va_start macro to initialize the va_list variable to an
argument list. 
- The macro va_start is defined in stdarg.h header file. 
- Use va_arg macro and va_list variable to access each item in argument list. 
- Use a macro va_end to clean up the memory assigned to va_list variable. 

