<pre class="slidecontent">

- new is used for dynamic allocation
- new operator calls operator new to allocate byte memory followed by calling default
constructor to initialize the object.
- new without parentheses does not initialize built in types where as calls default
constructor for class types
<pre class="code">int *pi = new int; // uninitialized
string *ps = new string; // initialized to empty string
</pre>

new when unsuccessful throws bad_alloc exception.
<pre class="code">                           ----------------
                           |  exception   |
                           ----------------
                                   |
       +---------------------------------------------------+
       |                  |             |                  |
--------------    ---------------  -------------    -------------
|  bad_cast  |    |runtime_error|  |logic_error|    | bad_alloc |
--------------    ---------------  -------------    -------------

 

new[] operator can be used to allocate array of values
new[] operator calls operator new[] followed by calling default constructor.
int *pi=new int[100];
</pre>
- value initialized then built in types are initialized where as class types as per
the argument. When no argument is passed then default constructor is called.
- value initialized
<pre class="code">string *ps = new string() ; // default constructor
int *pi = new int(); // pi points to an int value-initialized to 0
int *pi = new int(210); // pi points to an int value-initialized to 210
</pre>
- new calls operator new to allocate the bytes of memory followed by object creation
by calling default constructor.
<pre class="code">class classA{
public:
classA(const char* name):_name(name){}
const char* name(){return _name.c_str();}
private:
string _name;
};
int main(int argc, char *argv[]) {
classA *pc=new classA("heapallocation");
</pre></pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main3" class="pn">p34</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
<pre class="code">cout&lt;&lt;pc-&gt;name()&lt;&lt;endl;
return 0;
}
</pre>
- delete can not be used on a pointer that is not allocated through new
- delete can happen on NULL pointers.
- After deletion pointer can still be used but its illegal and undefined.
- Dynamic allocation to const objects uses new const statement
<pre class="code">const int *pci = new const int(1024);
delete pci;
</pre>
- delete[] operator deletes the array allocated through new[]
<pre class="code">int *pa=new int[4];
delete [] pa;
</pre>
