<pre class="code">#include &lt;iostream&gt;
using namespace std;

void printarray(int (&amp;arr)[4][4]){
int i=0,j=0;
for (i=0;i&lt;4;i++){
for (j=0;j&lt;4;j++)
cout&lt;&lt;arr[i][j]&lt;&lt;" ";
cout&lt;&lt;endl;
}
}
void preparearray(int (&amp;arr)[4][4]){
int i=0,j=0;
for (i=0;i&lt;4;i++)
for (j=0;j&lt;4;j++)
arr[i][j]=i;
}

int main(int argc,char *argv[]){
int arr[4][4];
preparearray(arr);
printarray(arr);
return 0;
}
