<pre class="slidecontent">

-There can be chance of same name collision. Ex. library function xyz() can collide
with user function xyz(). This is called namespace collision.
- Namespace provide a controlled mechanism for preventing name collision.  It provide
a separate scope in which functions and variable can be defined.
- Namespaces partition the global namespace, making it easier to use independently
produced libraries.
 
- Namespace definition
<pre class="code">namespace namespace_one {
}

#include &lt;iostream&gt;
using namespace std;
class classA {
public:
const char* name() {
return "Global class A";
}
};
// first name space
namespace first_space{
void func(){
cout&lt;&lt;"Inside first_space" &lt;&lt;endl;
}
class classA {
public:
const char* name() {
return "first_space::classA";
}
};
}
// second name space
namespace second_space{
void func(){
cout &lt;&lt; "Inside second_space" &lt;&lt; endl;
}
class classA {
public:
const char* name() {
return "second_space::classA";
}
};
}

int main ()
{

// Calls function from first name space.
first_space::func();
classA clsA_g;
first_space::classA clsA_f;
second_space::classA clsA_s;
cout&lt;&lt;clsA_g.name()&lt;&lt;endl;
cout&lt;&lt;clsA_f.name()&lt;&lt;endl;
cout&lt;&lt;clsA_s.name()&lt;&lt;endl;
// Calls function from second name space.
second_space::func();

return 0;
}
</pre>
- Namespace can be discontiguous. Writing namespace {} either defines a new namespace
or adds to an existing one.
- Discontiguous namespace can be used for declaration and definition separation, where
class definition, function declaration can go in namespace that is defined in a header
file where as class implementation and function definition can go in cpp file.
- When class is implemented in the discontiguous namespace class name would not
prepend the namespace name.
- To fetch global namespace functions :: can be used. i.e ::member_name


- Nestested Namespace
- Namespaces can be nested where you can define one namespace inside
</pre>
