<pre class="code">namespace namespace_name1 {
// code declarations
namespace namespace_name2 {
class classA{
};
}
}
</pre>
- Code in the outer parts of the enclosing namespace may refer to a name in a nested
namespaces only through its qualified name.
- Inner namespace variables can be used with full qualification, 
i.e. namespace_name1::namespace_name2::classA;

