- Unnamed Namesapces
- An unnamed namespace is a namespace that is defined without a name. i.e namespace {}
- Unnammed namespace can not span over files.
- Variable in global namespace can collide with unnamed namespace

<pre class="code">int i;
namespace {
int i;
}
i=10; // error
</pre>
- Since variables unnamed namespace belongs to the file it is replacement of static
variable and functions which also file visibility. static is deprecated in c++ against
unnamed namespace.
- If unnamed namespace is nested, then names in it are accessed in the normal way,
using the enclosing namespace name(s).

