<pre class="slidecontent">

A given namespace can contain a set of overload member functions.
1. Find the set of candidate functions. A function is a candidate if a declaration for
it is visible at the time of the call and it has the same name as the called function.

2. Select the viable functions from the set of candidates. A function is viable if it
has same number of parameters as the call has arguments and if each parameter could be
matched by the corresponding argument.

3. Select the single best match from the viable set and generate code to call that
function.
If the viable set is empty, then the call is in error, having no match
If the viable set is nonempty and there is no best match, then the call is ambiguous.
</pre>
