<pre class="slidecontent">

A programming language that provides
 - Class
A mechanism for defining our own abstract data types. Class may have properties,
methods and type members. A class defines a new type and a new scope.
- Object
An object is a region in the memory that has a type. Evaluating an expression that is
an lvalue yields an object. A variable is an object that has a name.
- Encapsulation
It describes the technique of combining lower-level elements to form a new high-level
identity.  Function and structures are examples of encapsulation.
- Abstraction
Separation of implementation from interface; Abstraction hides the implementation
details of a type. Programmers worry about internal data structure and users worry
about interfaces provided. Private data member are used for encapsulation.
- Inheritance
A derived class inherits properties from its base class. Types that are related by
inheritance share a common inheritance.
- Polymorphism
Derived from a Greek word, " many forms". It is ability to obtain type specific
behaviour based on the dynamic type of a reference or pointer.

