- Class
A mechanism for defining our own abstract data types. Class may have properties,
methods and type members. A class defines a new type and a new scope. Class itself is
a structure and consume 1 byte if not attributes are defined. Static members to
classes belongs to class data structure.

<pre class="code">class A{
};

- Class declaration
A class may be declared before it is defined.
class B;  // declaration
