- Class definition
A class body
- Abstract class
A class structure that uses encapsulation to hide its implementation, allowing
programmers using the type to think abstractly about what the type does rather than
concretely about how the type is represented.

- Concrete class
A class that exposes its implementation. i.e std::pair. All attributes are public

