implementation based inheritance.
- Protected members are accessible to friends, other class members and derived class
classes. It different from protected in order that derive class (public or protected
inheritance) can also use it. It comes under implementation based inheritance.
- Public members are accessible to everyone. It is mostly used as interface to the
user of class. public inheritance is also a interface base inheritance.

