- Constructor is a member function with name same as class name with no return type.
It has special privilege as it is called implicitly an class is instantiated.
Constructor can have arguments. when no argument is specified constructor is called
default constructor. Explicit default constructor does not implicit type conversion.
- Copy Constructor takes const reference to same class type as an argument to the
function. It is used to copy one object to other of same type.
- Synthesized constructor are constructors generated through compiler when it is not
provided by the programmer. If no constructor is provided then default constructor,
copy constructor, assignment operator and destructor is provided through the compiler.
If any of the constructor is provided then default constructor is not provided through
the compiler though other copy control can be synthesized if not available.
- Parametrized Constructor
A constructor can have parameters. This helps to assign initial value to an object at
