}
classA(const char *cp) {
cout&lt;&lt;"overload const char constructor :"&lt;&lt;cp&lt;&lt;endl;
}
classA&amp; operator=(const string&amp; str) {
cout&lt;&lt;"assignment operator "&lt;&lt;str&lt;&lt;endl;
return *this;
}
};
int main(int argc, char *argv[]) {
classA clsarr[] = { classA(string("one")),
    classA(string("two")),
    classA(string("three"))
};
func(string());
return 0;
}
</pre>
- More on copy constructor
&gt;Copy constructor should be declared private if copy need to be disabled, i.e.
ostream.
&gt;private copy constructor may need to declared but not defined if copy needs to be
disabled from friends and member functions.

&gt;Default behaviour of synthesized copy constructor is to do member wise copy. Shallow
copy.
- Synthesized Copy Constructor
&gt;When copy constructor is synthesized through compiler.
&gt;Unlike default constructor it is synthesized even though other constructors we
define.

- Parametrized constructor
- Other overloaded constructor can be declared as per the need.

- Assignment operator can be overloaded to define what it means to assign one object
of a class type to another of the same type. The assignment operator must be a member
of its class and should return a reference to its object. The compiler synthesizes the
assignment operator if the class does not explicitly define one.
- Assignment operator can be of non class type.
- Assignment operator can be compound type.
<pre class="code">#include &lt;iostream&gt;
using namespace std;
class classA {
public:
classA(){
_data="";
}
classA(const classA&amp; c) {
cout&lt;&lt;"copy constructor"&lt;&lt;endl;
}
classA&amp; operator=(const char* cp) {
cout&lt;&lt;"char pointer"&lt;&lt;endl;
_data+=cp;
return *this;
}
classA&amp; operator=(const string&amp; cs) {
cout&lt;&lt;"constant string"&lt;&lt;endl;
_data+=cs;
return *this;
}
classA&amp; operator=(char c) {
cout&lt;&lt;"char"&lt;&lt;endl;
_data+=c;
return *this;
}
classA&amp; operator+=(const classA&amp; rhs) {
_data+=rhs._data;
return *this;
}
string&amp; data() {
return _data;
}
private:
string _data;
};

int main() {
classA cls;
cls = "one";
cls = string(":two");
cls=':';
classA rhs;
rhs="three";
</pre></pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main5" class="pn">p44</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
