<pre class="code">cls+=rhs;
cout&lt;&lt;"cls data : "&lt;&lt;cls.data()&lt;&lt;endl;
return 0;
}
</pre>
- Destructor
A destructor is a special member function of a class that is executed whenever an
object of it's class goes out of scope or whenever the delete expression is applied to
a pointer to the object of that class.

- A destructor will have exact same name as the class prefixed with a tilde (~) and it
can neither return a value nor can it take any parameters.
- Destructor can be very useful for releasing resources before coming out of the
program like closing files, releasing memories etc.

<pre class="code">#include &lt;iostream&gt;
using namespace std;
class Line{
public:
double length( void );
Line();   // This is the constructor declaration
~Line();  // This is the destructor: declaration
private:
double _length;
};
// Member functions definitions including constructor
Line::Line(void){
cout &lt;&lt; "Object is being created" &lt;&lt; endl;
_length=0;
}
Line::~Line(void){
cout &lt;&lt; "Object is being deleted" &lt;&lt; endl;
}
double Line::length( void ){
return _length;
}
// Main function for the program
int main( ){
Line line;
cout &lt;&lt; "Length of line : " &lt;&lt; line.length() &lt;&lt;endl;
return 0;
}
</pre>
