<pre class="slidecontent">
- Data abstraction refers to, providing only essential information to the outside
world and hiding their background details,  i.e., to represent the needed information
in program without presenting the details.
- Data abstraction is a programming (and design) technique that relies on the
separation of interface and implementation.
- Data abstraction layer also known as interfaces must not contain any attributes and
only operations should be supported either pure virtual or default implementation
implemented.

<pre class="code">class ITelevision {
public:
virtual void switchto(bool onoff=0) = 0;
virtual void volume(int level) = 0;
virtual void channel(int number) = 0;
};
class modeltelevision: public ITelevision {
public:
virtual void switchto(bool onoff) {
cout&lt;&lt;"Tv is switched "&lt;&lt;(onoff?" ON ": " OFF ")&lt;&lt;endl;
}
virtual void volume(int level) {
cout&lt;&lt;"Volume raised to : "&lt;&lt;level&lt;&lt;endl;
}
virtual void channel(int number) {
cout&lt;&lt;"channel number : "&lt;&lt;number&lt;&lt;endl;
}
};
int main(int argc, char *argv[]) {
ITelevision *tv=new modeltelevision;
tv-&gt;switchto(true);
tv-&gt;channel(5);
tv-&gt;volume(8);
tv-&gt;switchto(false);
return 0;
}
</pre>
