 </div>
<pre class="slidecontent">

- Data or function member that is not a part of any object but is shared by all
objects of a given class. Static is part class structure.

- Static methods can not call member variables not static as they are part of object
structure.
- Static methods does not contain this pointer.
- No polymorphism on static methods. It can not be virtual.
- We can define class members static using static keyword. When we declare a member of
a class as static it means no matter how many objects of the class are created, there
is only one copy of the static
member.
- A static member is shared by all objects of the class. All static data is
initialized to zero when the first object is created, if no other initialization is
present.

- By declaring a function member as static, you make it independent of any particular
object of the class. A static member function can be called even if no objects of the
class exist.
- A static member function can only access static data member, other static member
functions and any other functions from outside the class.
- Static member functions have a class scope and they do not have access to the this
pointer of the class.

<pre class="code">#include &lt;iostream&gt;
using namespace std;
class Box{
public:
static int objectCount;
Box(double l=2.0, double b=2.0, double h=2.0){
cout &lt;&lt;"Constructor called." &lt;&lt; endl;
length = l;
breadth = b;
height = h;
objectCount++;
}
double Volume(){
return length * breadth * height;
}
static int getCount(){
return objectCount;
}
private:
double length;     // Length of a box
double breadth;    // Breadth of a box
double height;     // Height of a box
};
int Box::objectCount = 0;
int main(void){
cout &lt;&lt; "Inital Stage Count: " &lt;&lt; Box::getCount() &lt;&lt; endl;
Box Box1(3.3, 1.2, 1.5);    // Declare box1
Box Box2(8.5, 6.0, 2.0);    // Declare box2
cout &lt;&lt; "Final Stage Count: " &lt;&lt; Box::getCount() &lt;&lt; endl;
return 0;
}
</pre>
