<pre class="slidecontent">

- A friend function of a class is defined outside that class scope but it has the
right to access all private and protected members of the class.
- Even though the prototypes for friend functions appear in the class definition,
friends are not member functions.
- A friend can be a function, function template, or member function, or a class or
class template, in which case the entire class and all of its members are friends.
- To declare a function as a friend of a class, precede the function Prototype in the
class definition with keyword friend as follows:

<pre class="code">#include &lt;iostream&gt;
using namespace std;
class Box {
double width;
public:
friend void printWidth( Box box );
void setWidth( double wid );
};
void Box::setWidth( double wid ) {
width = wid;
}
void printWidth( Box box ) {
cout << "Width of box : " << box.width <<endl;
}

int main( ) {
Box box;
box.setWidth(10.0);
printWidth( box );
return 0;
}
</pre>
- Friend class similar to friend function gets access to friends all
attributes and methods. A friend class though have no special access
to base or derived class of the class to which it friend with.

<pre class="code">class A{
protected int a;
};
class B:publlic A{
private int b;
friend class D;
};
class D{
public:
void print(A apar){
cout&lt;&lt;apar.b;
}
};
</pre>
