<pre class="slidecontent">

- Default Constructor
 - Constructor having no parameter is default constructor. Default in the sense if
object is constructed with any argument passed then this constructed gets called.
 - A synthesized default constructor is provided by the compiler in case there is no
other constructor available for the class.

 - Default constructor can be overloaded in fashion that other functions are
overloaded in c++. It can have default parameter values also. Overloaded functions
comes under two categories

- Copy Constructor
- Parametrized constructor

- Copy Constructor
- Copy constructor falls in a category called Copy Control. Copy constructor is used
at following places
- The constructor that takes single parameter (const reference) as argument to class
type itself.

- Explicity or implicitly initialize one object from another of the same type.
<pre class="code">string securityId="99999-99999-99999";
string securityId2=securityId;
string securityId2(securityId);
</pre>
- Copy an object to pass it as an argument to a function.
string secuirtyId="123-123-123";
<pre class="code">void func(const string secid);
func(secuirtyid);
</pre>
- Copy an object to return it from a function.
<pre class="code">string make_plural(size_t s, const string&amp; str, const string&amp; end) {
return (size == 1?str:str+end);
}
</pre>
- Initialize the elements in a sequential container.
<pre class="code">vector&lt;string&gt; stringvec(5);
</pre>
This creates five temporary string object with default constructor and then creates
five vector strings calling its copy constructor on five temporary objects.
- Initialize elements in an array from a list of element initializers
<pre class="code">string stringarry[] = { "one", "two", "three"}

#include &lt;iostream&gt;
using namespace std;
void func(string str) {
cout&lt;&lt;"string : "&lt;&lt;str&lt;&lt;endl;
}
class classA {
public:
classA() {
cout&lt;&lt;"default constructor"&lt;&lt;endl;
}
classA(const classA&amp; cls) {
cout&lt;&lt;"copy constructor"&lt;&lt;endl;
}
explicit classA(const string&amp; str) {
cout&lt;&lt;"overloaded constructor : "&lt;&lt;str&lt;&lt;endl;
}
classA(const char *cp) {
cout&lt;&lt;"overload const char constructor :"&lt;&lt;cp&lt;&lt;endl;
}
classA&amp; operator=(const string&amp; str) {
cout&lt;&lt;"assignment operator "&lt;&lt;str&lt;&lt;endl;
return *this;
}
};
int main(int argc, char *argv[]) {
classA clsarr[] = { classA(string("one")),
                    classA(string("two")),
                    classA(string("three"))
</pre></pre>
