<pre class="slidecontent">

When copy constructor is synthesized through compiler.
Unlike default constructor it is synthesized even though other constructors we define.
- More on copy constructor
Copy constructor should be declared private if copy need to be disabled,
i.e. ostream.
private copy constructor may need to declared but not defined if copy needs to be
disabled from friends and member functions
Default behaviour of synthesized copy constructor is to do member wise copy. Shallow
copy.

