<pre class="slidecontent">

Assignment operator can be member or non member functions.  for member function first
member of the function is bound to 'this' pointer.
<pre class="code">struct A{
A&amp; operator=(const A&amp;);
}
void operator=(const A&amp;,const A&amp;);
</pre>- synthesized assignment operator
if assignment operator is not available compiler pushes a synthesized.
- does member wise copy (shallow for pointer)
- does array member index wise copy
<pre class="code">A a;
A b=a; // copy constructor


#include &lt;iostream&gt;
using namespace std;
class classA {
public:
classA(){
_data="";
}
classA(const classA&amp; c) {
cout&lt;&lt;"copy constructor"&lt;&lt;endl;
}
classA&amp; operator=(const char* cp) {
cout&lt;&lt;"char pointer"&lt;&lt;endl;
_data+=cp;
return *this;
}
classA&amp; operator=(const string&amp; cs) {
cout&lt;&lt;"constant string"&lt;&lt;endl;
_data+=cs;
return *this;
}

classA&amp; operator=(char c) {
cout&lt;&lt;"char"&lt;&lt;endl;
_data+=c;
return *this;
}
classA&amp; operator+=(const classA&amp; rhs) {
_data+=rhs._data;
return *this;
}
string&amp; data() {
return _data;
}
private:
string _data;
};
int main() {
classA cls;
cls = "one";
cls = string(":two");
cls=':';
classA rhs;
rhs="three";
cls+=rhs;
cout&lt;&lt;"cls data : "&lt;&lt;cls.data()&lt;&lt;endl;
return 0;
}
</pre>
