<pre class="slidecontent">

Destructor is automatically called when an object is released from the memory, either
because its scope of existence has finished (for example, if it was defined as a local
object within a function and the function ends) or because it is an object dynamically
assigned and it is released using operator delete.
</pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main7" class="pn">p55</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">

The destructor must have the same name as the class with a tilde (~) as prefix and it
must return no value.
- destructor is synthesised by compiler if not declared
- destructor can be virtual to support polymorphism and get derived class
  destructor called with delete on base class pointer.
- destructor can be called as method.

<pre class="code">// example on constructors and destructors
#include &lt;iostream.h&gt;
class CRectangle {
int *width, *height;
public:
CRectangle (int,int);
~CRectangle ();
int area (void) {return (*width * *height);}
};
CRectangle::CRectangle (int a, int b) {
width = new int;
height = new int;
*width = a;
*height = b;
}
CRectangle::~CRectangle () {
delete width;
delete height;
}
int main () {
CRectangle rect (3,4), rectb (5,6);
cout &lt;&lt; "rect area: " &lt;&lt; rect.area() &lt;&lt; endl;
cout &lt;&lt; "rectb area: " &lt;&lt; rectb.area() &lt;&lt; endl;
return 0;
}
</pre>
