<pre class="slidecontent">

- In order to maintain uniform representation of objects for all classes table driven
object model places attributes and methods to two different tables. 
The class object contains the pointers to the two member tables. The member function
table is a sequence of slots, with each slot addressing a member. The data member
table directly holds the data.

<pre class="code">                                     attribute
                         |--------&gt; -----------------
                         |          |         x |
                         |          --------------
                         |          |         y |
                         |          ---------------
        -------------    |
        |           |    |
        |       o---------
        -------------
        |           |
        |       o---------
        -------------    |
          Point pt;      |            method
                         |-------&gt; --------------
                                   |         o--|----&gt;
                                   --------------
                                   |         o--|----&gt;
                                   --------------
                                   |         o--|----&gt;
                                   --------------
</pre>
