--------- &lt;-- A*,C*----------
| a:int | --------| A::f(int);
| vptr  |         | C::h(int);
--------- &lt;-- B*  ------------
| b:int |
---------
| c:int |
---------

C* pc;
B* pb;
pb = (B*)pc; // pb = (B*)((char*)pc+delta(B))
pb = pc; // pb = (B*)((char*)pc+delta(B))
pc = pb; // error: cast needed
pc = (C*)pb; // pc = (C*)((char*)pb-delta(B))


-delta storage.
class A{virtual void f();};
class B{virtual void f(); virtual void g();};
class C:A , B{void f();};
A* pa=new C;
B* pb=new C;
C* pc=new C;
pa-&gt;f();
pb-&gt;f();
pc-&gt;f();
</pre>
In order to fix this pointer when calling the base class function in context of
derived class object detla mechanism is used.

In order to shift top to pb* place delta(B) is calculated at compile time.

In order to have it at run time it is stored in vtable where function entry is a
structure itself with first field is a function pointer and second field as delta(B).

<pre class="code">struct vtbl_entry{
void  (*fct)();
int delta;
};

-------------  vtbl    -------------
|  vtpr     | -------&gt; | &amp;C::f()| 0 |
| A part    |          -------------
-------------
|           | vtbl    ----------------------
| vptr      | ------&gt; | &amp;C::f()| - delta(B)|
| B part    |         ----------------------
-------------         | &amp;B::g()| 0 |
|           |         --------------
| C part    |
-------------


B* pb=new C;
pb-&gt;f();
</pre></pre>
