- virtual base
<pre class="code">class W {
 virtual void f();
 virtual void g();
 virtual void h();
 virtual void k();
};
class AW:virtual W{ void g();...};
class BW:virtual W{ void f();...};
class CW:AW, BW { void h();....};
CW* pcw=new CW;
pcw-&gt;f();  //BW::f()
pcw-&gt;g();  /AW::g()
pcw-&gt;h();  //CW::h()
((AW*)pcw)-&gt;f();   /BW::f();


          -----------------
......... |
.         | AW part |
v         |         |
.         -----------------
......... |
.         | BW part |
v         |         |
.         -----------------
.         |         |
.         | CW part |
v         |         |        vtbl:
.         ----------------- ------------------------------
...&gt;      | vptr ..........&gt;| BW::f | delta(BW)-delta(W) |
          |         |       | AW::g | -delta(W) |
          | W part  |       | CW::h | -delta(W) |
          |         |       | W::k  | 0         |
          ----------------- ------------------------------



....&gt; W { f g h k } &lt;...
|          |
            
|          |
AW { g }          BW { f }
|          |
            
|          |
...&lt;... CW { h } ...&gt;...
</pre>
Note that a call ''up'' through one path of the DAG to a virtual function may result
in the call of a function (re-defined) in another path (as happened in the call
((AW*)pcw)-&gt;f() in the example above).

