-Thunk based object model, vtable entry is not two field structures instead it is has
function pointer to virtual function. vtable of base class contains thunk entries for
functions which is overridden by derived class. Aduster thunk actually adjust the this
pointer first then call the function in unsimilar to offset based approach where base
class function entry from the vtable was called with adjusted this pointer.
