 <a name="chap9">&nbsp;<div class="slideheader" style="height:185px">
  <pre class="day">Day 3 Morning</pre>
  <pre class="topic">  9. Inheritance</pre>
  <ul class="slidecontent">
   <li class="big"><a name="chap9_0">Base class and drive class</a></li>   <li class="sml"><pre>Virtual methods
</pre></li>   <li class="sml"><pre>Pure virtual methods
</pre></li>   <li class="sml"><pre> Changing scope of base member in derived classes
</pre></li>   <li class="sml"><pre>Multiple inheritance
</pre></li>   <li class="sml"><pre>Polymorphism
