</pre></li>   <li class="sml"><pre>Interface and Implementation inheritance</pre></li>
  </ul>
 </div></a>
<pre class="slidecontent">

- Base class
Class from which another class inherits. The members of the base class become members
of the derived class.


- Derived class
A class inherits from another class. Member of the base class are also members of the
derived class. Parent attributes and methods can be called in Derived class context.
Base class object comes inside of derive class 
object.

<pre class="code">struct A:B{
};
A *, B* --&gt; +-------------+
            |   B::b:int  |
            ---------------
            |   A::a:int  |
            +-------------+
</pre>
A derived class can redefine the members of its base (function overriding) and can
define new members. A derived-class scope is nested in the scope of its base class, so
the derived class can access members of the base class 
directly.

- Inheritance allows us to define a class in terms of another class, which makes it
easier to create and maintain an application.
- This also provides an opportunity to reuse the code functionality and fast
implementation time.
- When creating a class, instead of writing completely new data members and member
functions, the programmer can designate that the new class should inherit the members
of an existing class. This existing class is called the base class, and the new class
is referred to as the derived class.
- The idea of inheritance implements the is a relationship. For example,
mammal IS-A animal, dog IS-A mammal hence dog IS-A animal.

- A class can be derived from more than one classes, which means it can inherit data
and functions from multiple base classes.  class derived-class: access-specifier
base-class

<pre class="code">Access                public  protected  private
Same class            yes     yes        yes
Derived classes       yes     yes        no
Outside classes       yes     no         no
</pre>
- A derived class inherits all base class methods with following exceptions:
Constructors, destructors and copy constructors of the base class.
Overloaded operators of the base class.
The friend functions of the base class.

</pre><pre class="ftr">&copy www.minhinc.com</pre><a href="#main9" class="pn">p63</a>
