- A virtual function declared in the class header using =0 at the end of the
function's parameter list.  A pure virtual is one that need not be (but may be)
defined by the class. A class with a pure virtual is an abstract class. If a derived
class does not define its own version of an inherited pure virtual, then the derived
class is abstract as well.

