- Inheritance in which a class has more than one immediate base class.
The derived class inherits the members of all its base classes. Multiple base classes
are defined by naming more than one base class in the class derivation list. A
separate access label is required for each base class.

- Multiple inheritance is useful when an entity carries multiple identity. 
Multiple type of task can be performed on the same object.  A multi homed computer can
be a router or a server.

