- Polymorphism means "many forms". It refers to obtain type specific behaviour based
on the dynamic type of a reference or pointer.

In inheritance base class shows polymorphic behaviour. Base class pointer accept down
the line derived class concrete objects.

<pre class="code">                                          f()
                                       &lt;|---- B
                            A  &lt;|----- |      &lt;|------ D
                            f()        &lt;|---- C        f(),g()
                                          g()

void func(A* pa){  &lt;--- A* is polymorphic and accepts object of derived class B,C,D
pa-&gt;f();// always bound to base A::f(). A::f() is not polymorphic
func(new B);
func(new C);
func(new D);
</pre>
When a function in base class is virtual then function becomes polymorphic
<pre class="code">                                      virtual f()
                                       &lt;|---- B
                            A  &lt;|----- |      &lt;|------ D
                    virtual f()        &lt;|---- C        f(),g()
                                      Virtual g()

void func(A* pa){
ps-&gt;f();// polymorphic
}
func(new B);//pa-&gt;f() calls B::f()
func(new D);// pa-&gt;f() calls D::f()
</pre>
