cout&lt;&lt;"A::func"&lt;&lt;endl;
}
};
struct B:A{
void func(float y){
cout&lt;&lt;"B::func"&lt;&lt;endl;
}
};

int main(){
A* pa=new B;
pa-&gt;func(10); // resolves to A::func
return 0;
}
