<pre class="slidecontent">

-A publicly derived class inherits the interface of its base class. It has the same
interface as its base class. In well designed class hierarchies object of a publicly
derived class can be used wherever an object of the base 
class is expected.
Classes derived using protected or private inheritance do not inherit the base class
interface. Instead these derivations are often referred to as implementation
inheritance. The derived class uses the inherited class in its implementation but does
not expose the fact of the inheritance as part of its interface..

$ cat main.cpp
<pre class="code">#include &lt;iostream&gt;
using namespace std;
class A{
public:
int pl;
private:
int pr;
};
class B:private A{ //implementation inheritance
public:
using A::pl; //still pl can be accessible
B(){pl=20;}
//using A::pr;//error
private:
//using A::pr;//error
};
int main(){
B b;
cout<<"B::pl"<<b.pl<<endl;
return 0;
}
</pre>
$ ./a.out 
<pre class="code">B::pl20
</pre>
