<pre class="slidecontent">

ostream_iterators are used to write a sequence of value to a stream in much the same
way that we might use and iterator to assign a sequence of values to the elements of a
container.

<pre class="code">ostream_iterator&lt;string&gt; out_iter(cout,"\n");
istream_iterator&lt;string&gt; in_iter(cin),eof;
while(in_iter != eof)
*out_iter++ = *in_iter++;
</pre>

Limitations of steam iterators
- It is not possible to read from an ostream_iterator and it not possible to write to
an istream_iterator. 
- Once we assign a value to an ostream_iterator, the write is committed
- There is no -&gt; operator for ostream-iterator

Sorting input from console
