<pre class="slidecontent">

- There are various relational operators supported by C++ language like (&lt;, &gt;, &lt;=, &gt;=,
==, etc.) which can be used to compare C++ built-in data types.

<pre class="code">#include &lt;iostream&gt;
using namespace std;
class Distance {
int feet;
int inches;
public:
Distance(int f=0, int i=0) {
feet = f;
inches = f;
}
friend bool operator &lt;(const Distance&amp; dl, const Distance &amp;dr);
};
bool operator &lt;(const Distance&amp; dl, const Distance &amp;dr) {
if(dl.feet &lt; dr.feet) {
return true;
}
if(dl.feet == dr.feet &amp;&amp; dl.inches &lt; dr.inches) {
return true;
}
return false;
}
int main()
{
Distance d1(11, 10), d2(5, 11);
if( d1 &lt; d2 )   {
cout &lt;&lt; "d1 is less than d2 " &lt;&lt; endl;
}   else   {
cout &lt;&lt; "d2 is less than d1 " &lt;&lt; endl;
}
return 0;
}
</pre>
