- The unary operators operate on a single operand. 
  - The increment (++) and decrement (--) operators.
  - The unary minus (-) operator.
  - The logical not (!) operator.


- This operator appears on the left side of the object, as in !obj, -obj, and ++obj
but sometime they can be used as postfix as well like obj++ or obj--.

<pre class="code">#include&lt;iostream&gt;
using namespace std;
class Distance{
private:
int feet;
int inches;
public:
Distance(int f=0,int i=0){
feet = f;
inches = i;
}
int gfeet() {
return feet;
}
int ginches() {
return inches;
</pre></pre>
