<pre class="slidecontent">
<pre class="code">}
Distance(const Distance&amp; d) {
feet=d.feet;
inches=d.inches;
}
Distance operator- ()
{
feet = -feet;
inches = -inches;
return Distance(feet, inches);
}
Distance&amp; operator++() {
if(++inches == 12) {
inches=0;
++feet;
}
return *this;
}

Distance operator++(int) {
Distance d(*this);
++*this;
return d;
}
};
int main()
{
Distance d1(11, 10), d2(-5, 11);
-d1;
cout&lt;&lt;"feet : inches "&lt;&lt;d1.gfeet()&lt;&lt;" : "&lt;&lt;d1.ginches()&lt;&lt;endl;
-d2;
cout&lt;&lt;"feet : inches "&lt;&lt;d2.gfeet()&lt;&lt;" : "&lt;&lt;d2.ginches()&lt;&lt;endl;
d1.operator++(0);
cout&lt;&lt;"feet : inches "&lt;&lt;d1.gfeet()&lt;&lt;" : "&lt;&lt;d1.ginches()&lt;&lt;endl;
d2.operator++();
cout&lt;&lt;"feet : inches "&lt;&lt;d2.gfeet()&lt;&lt;" : "&lt;&lt;d2.ginches()&lt;&lt;endl;
return 0;
}
