<pre class="slidecontent">

 - A conversion operator defines a conversion that converts a value of a class type to
some other type.

<pre class="code">#include &lt;iostream&gt;
#include &lt;stdexcept&gt;
using namespace std;
class classA {
public:
classA(int i=0):_val(i) {
if(i&lt;0 || i&gt;255)
throw out_of_range("Bad classA initializer");
}
operator int() const {return _val;}
private:
std::size_t _val;
};
int main() {
classA *cls;
try {
cls=new classA(10);
}
catch(const exception&amp; e) {
cout&lt;&lt;"exception cought : "&lt;&lt;e.what()&lt;&lt;endl;
return -1;
}
cout&lt;&lt;" cls value : "&lt;&lt;*cls;
delete cls;
return 0;
}
</pre>
