<pre class="slidecontent">

- Templates are the foundations of generic programming, which involves writing code in
a way that is independent of any particular type.
- A template is a blueprint or formula for creating a generic class or a function. The
library containers like iterators and algorithms are examples of generic programming
and have been developed using template concept.
- There is a single definition of each container, such as vector, but we can define
many different kinds of vectors for example, vector &lt;int&gt; or vector &lt;string&gt;.
- Templates can be used to define functions as well as classes


</pre> &nbsp;<div class="slideheader" style="height:175px">
  <pre class="day">Day 4 Morning</pre>
  <pre class="topic">  12. Templates</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>Generic class
</pre></li>   <li class="big"><a name="chap12_1">Class template</a></li>   <li class="sml"><pre>Template argument deduction
</pre></li>   <li class="sml"><pre>Function template explicit arguments
</pre></li>   <li class="sml"><pre> Function template friend function and class
</pre></li>   <li class="sml"><pre>Specialization
</pre></li>   <li class="sml"><pre> Template bloating
</pre></li>   <li class="sml"><pre>Sequential standard template libraries
</pre></li>   <li class="sml"><pre>Associative standard template libraries</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

 - The general form of a generic class declaration is shown here:
template &lt;class type&gt; class class-name {
.
.
.
}

- Here, type is the placeholder type name, which will be specified when a class is
instantiated. You can define more than one generic data type by using a
comma-separated list.

<pre class="code">#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;cstdlib&gt;
#include &lt;string&gt;
#include &lt;stdexcept&gt;
using namespace std;
template &lt;class T&gt;
class Stack {
private:
vector&lt;T&gt; elems;     // elements
public:
void push(T const&amp;);  // push element
void pop();               // pop element
T top() const;            // return top element
bool empty() const{       // return true if empty.
return elems.empty();
}
};
template &lt;class T&gt;
void Stack&lt;T&gt;::push (T const&amp; elem) {
elems.push_back(elem);
}
template &lt;class T&gt;
void Stack&lt;T&gt;::pop () {
if (elems.empty()) {
throw out_of_range("Stack&lt;&gt;::pop(): empty stack");
}
elems.pop_back();
}
template &lt;class T&gt;
T Stack&lt;T&gt;::top () const {
if (elems.empty()) {
throw out_of_range("Stack&lt;&gt;::top(): empty stack");
}
return elems.back();
}
int main() {
</pre></pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main12" class="pn">p77</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
<pre class="code">try {
Stack&lt;int&gt;         intStack;  // stack of ints
Stack&lt;string&gt; stringStack;    // stack of strings
intStack.push(7);
cout &lt;&lt; intStack.top() &lt;&lt;endl;
stringStack.push("hello");
cout &lt;&lt; stringStack.top() &lt;&lt; std::endl;
stringStack.pop();
stringStack.pop();
}
catch (exception const&amp; ex) {
cerr &lt;&lt; "Exception: " &lt;&lt; ex.what() &lt;&lt;endl;
return -1;
}
}
</pre>
- The general form of a template function definition is as following

template &lt;class type&gt; ret-type func-name(parameter list)
<pre class="code">{
// body of function
}
template &lt;typename T&gt;
inline T const&amp; Max (T const&amp; a, T const&amp; b)
{
return a < b ? b:a;
}
</pre>
- Function templates parameters can be type parameter and non type parameter
- Type name string can be typename or class, it can be used interchangeably

<pre class="code">template&lt;class A, class U&gt;
A func(A* array, U value) {
A::size_type *p; // misleading, if typename then p is declaration otherwise
multiplication
}

template&lt;class A, class U&gt;
A func(A *array, U value) {
typename A::size_type *p;
}

#include &lt;iostream&gt;
#include &lt;string&gt;
using namespace std;
template &lt;typename T&gt;
inline T const&amp; Max (T const&amp; a, T const&amp; b)
{
return a < b ? b:a;
}
int main ()
{
int i = 39;
int j = 20;
cout &lt;&lt; "Max(i, j): " &lt;&lt; Max(i, j) &lt;&lt; endl;
double f1 = 13.5;
double f2 = 20.7;
cout &lt;&lt; "Max(f1, f2): " &lt;&lt; Max(f1, f2) &lt;&lt; endl;
string s1 = "Hello";
string s2 = "World";
cout &lt;&lt; "Max(s1, s2): " &lt;&lt; Max(s1, s2) &lt;&lt; endl;
return 0;
}
</pre>
