-The process of determining the types and values of the template arguments from the
type of the function argument is called template argument deduction.
-If a template type is used as the type of more than one function parameter template
type deduction must generate the same template argument type for each corresponding
function argument.

<pre class="code">template &lt;typenaem T&gt;
int compare (const T&amp; v1, const T&amp; v2){
if(v1 &lt; v2) return -1;
</pre></pre>
