compare(si,1024);//error
</pre>
- Limited conversions on type parameter arguments
Arguments are not converted to match an existing instantiations, instead a new
instance is generated.

- In two cases new instance would not be generated
&gt; const conversion: A function that takes a reference or pointer to a const can be
called with reference or pointer to non const object respectively with generating a
new instantiation.
&gt; array or function to pointer conversions: if the template parameter is not a
reference type then normal pointer conversion will be applied to argument of array or
function type.

-Template argument deduction and function pointer

<pre class="code">template&lt;typename T&gt;int compare(const T&amp;, const T&amp;);
int (*pf1)(const int&amp;, const int&amp;) = compare;
</pre>
