- There are three scenarios when friends appear to a template class or template
function.
&gt; A friend declaration for an ordinary non template class of function, which grants
friendship to the specific named class of function.

<pre class="code">template &lt;class type&gt; class Bar{
 friend class A;
 friend void fcn();
};
</pre> 
&gt; A friend declaration for a class template or function template, which grants access
to all instances of the friend.

<pre class="code">template&lt;class type&gt; class Bar{
template &lt;class T&gt; friend class Fool;
template &lt;class T&gt; friend void templ_frnl(const T&amp;);
};
</pre>
&gt; A friend declaration that grants access only to a specific instance of a class or
function template.
 
<pre class="code">template &lt;class T&gt; class Foo2;
template &lt;class T&gt; void templ_func2(const T&amp;);
template &lt;class Type&gt; class Bar{
