 <a name="chap13">&nbsp;<div class="slideheader" style="height:165px">
  <pre class="day">Day 4 Afternoon</pre>
  <pre class="topic">  13. Exception handling</pre>
  <ul class="slidecontent">
   <li class="big"><a name="chap13_0">Resumption and termination</a></li>   <li class="sml"><pre>Stack unwinding
</pre></li>   <li class="sml"><pre>Throwing and catching exception
</pre></li>   <li class="sml"><pre>Polymorphism
</pre></li>   <li class="sml"><pre>set_terminate function
</pre></li>   <li class="sml"><pre>Function try block and exception.
</pre></li>   <li class="sml"><pre>Exception specification
</pre></li>   <li class="sml"><pre>Function pointer exception specifications</pre></li>
  </ul>
 </div></a>
<pre class="slidecontent">

- An exception is a problem that arises during the execution of a program.  A C++
exception is a response to an exceptional circumstance that arises while a program is
running, such as an attempt to divide by zero.
- Exceptions provide a way to transfer control from one part of a program to another.
C++ exception handling is built upon three keywords: try, catch, and throw.
 - throw: A program throws an exception when a problem shows up. This is done using a
throw keyword.
 - catch: A program catches an exception with an exception handler at the place in a
program where you want to handle the problem. The catch keyword indicates the catching
of an exception.
 - try: A try block identifies a block of code for which particular exceptions will be
activated. It's followed by one or more catch blocks.

 - Assuming a block will raise an exception, a method catches an exception using a
combination of the try and catch keywords. A try/catch block is placed around the code
that might generate an exception. Code within a try/catch block is referred to as
protected code. 

<pre class="code">try
{
   // protected code
}
catch( ExceptionName e1 ) {
   // catch block
}
catch( ExceptionName e2 ) {
   // catch block
}
catch( ExceptionName eN ) {
   // catch block
}
</pre>

If an exception is not caught by any catch statement because there is no
catch statement with a matching type, the special function terminate will
be called.

</pre> &nbsp;<div class="slideheader" style="height:165px">
  <pre class="day">Day 4 Afternoon</pre>
  <pre class="topic">  13. Exception handling</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>Resumption and termination
</pre></li>   <li class="big"><a name="chap13_1">Stack unwinding</a></li>   <li class="sml"><pre>Throwing and catching exception
</pre></li>   <li class="sml"><pre>Polymorphism
</pre></li>   <li class="sml"><pre>set_terminate function
</pre></li>   <li class="sml"><pre>Function try block and exception.
</pre></li>   <li class="sml"><pre>Exception specification
</pre></li>   <li class="sml"><pre>Function pointer exception specifications</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

- The process known as stack unwinding continues up the chain of nested function calls
until a catch clause for the exception is found.
- During stack unwinding the function containing the throw and possibly other
functions  in the call chain are exited prematurely.
- During stack unwinding destructors are called against local objects.
- Do not throw exception in destructor as there would be multiple throws to catch and
would miss the genuine exception raised and may end in calling terminate function.  

</pre><pre class="ftr">&copy www.minhinc.com</pre><a href="#main13" class="pn">p82</a>
</div> <div class="pg" style="margin-top:20px;height:1395px">
 &nbsp;<div class="slideheader" style="height:165px">
  <pre class="day">Day 4 Afternoon</pre>
  <pre class="topic">  13. Exception handling</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>Resumption and termination
</pre></li>   <li class="sml"><pre>Stack unwinding
</pre></li>   <li class="big"><a name="chap13_2">Throwing and catching exception</a></li>   <li class="sml"><pre>Polymorphism
</pre></li>   <li class="sml"><pre>set_terminate function
</pre></li>   <li class="sml"><pre>Function try block and exception.
</pre></li>   <li class="sml"><pre>Exception specification
</pre></li>   <li class="sml"><pre>Function pointer exception specifications</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

Throwing Exceptions:
Exceptions can be thrown anywhere within a code block using throw statements. The
operand of the throw statements determines a type for the exception and can be any
expression and the type of the result of the expression determines the type of
exception thrown.

<pre class="code">double division(int a, int b) {
if( b == 0 ) {
throw "Division by zero condition!";
}
return (a/b);
}
</pre>
Catching Exceptions
The catch block following the try block catches any exception. 
<pre class="code">try  {
  // protected code
}
catch( ExceptionName e )  {
// code to handle ExceptionName exception
}
</pre>
- Above code will catch an exception of ExceptionName type. 
- catch block should handle any type of exception that is thrown in a try block,
an ellipsis, ..., between the parentheses enclosing the exception declaration.

<pre class="code">try
{
   // protected code
}catch(...)
{
  // code to handle any exception
}

#include &lt;iostream&gt;
using namespace std;

double division(int a, int b)
{
if( b == 0 )
{
throw "Division by zero condition!";
}
return (a/b);
}

int main ()
{
int x = 50;
int y = 0;
double z = 0;
try {
z = division(x, y);
cout &lt;&lt; z &lt;&lt; endl;
}catch (const char* msg) {
cerr &lt;&lt; msg &lt;&lt; endl;
}

return 0;
}
</pre>
</pre><pre class="ftr">&copy www.minhinc.com</pre><a href="#main13" class="pn">p83</a>
</div> <div class="pg" style="margin-top:20px;height:1395px">
 &nbsp;<div class="slideheader" style="height:165px">
  <pre class="day">Day 4 Afternoon</pre>
  <pre class="topic">  13. Exception handling</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>Resumption and termination
</pre></li>   <li class="sml"><pre>Stack unwinding
</pre></li>   <li class="sml"><pre>Throwing and catching exception
</pre></li>   <li class="big"><a name="chap13_3">Polymorphism</a></li>   <li class="sml"><pre>set_terminate function
</pre></li>   <li class="sml"><pre>Function try block and exception.
</pre></li>   <li class="sml"><pre>Exception specification
</pre></li>   <li class="sml"><pre>Function pointer exception specifications</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

Exception thrown can be caught through parent class reference.

