<pre class="slidecontent">

To handle an exception from the constructor initializer, we must write the constructor
as a function try block.

<pre class="code">template &lt;class T&gt; Handle&lt;T&gt;::Handle(T *p)
try : ptr(p),use(new size_t(1))
{
}catch(const std::bad_alloc &amp;e)
{ handle_out_of_memor(e);}
</pre>
- function try precedes the member initialization
- the catch clause can handle exceptions thrown either from within the member
initialization list or from within the constructor body.


