Operator new is an operator which allocates memory in bytes rather than in object type
size. It comes in two variations <pre class="code" style="display:inline">void *operator new(size_t)</pre> and void
<pre class="code" style="display:inline">*operator new[](size_t)</pre>

<pre class="code">void *operator new(size_t) // allocates memory of size_t bytes analogous to malloc
void *operator new[] (size_t) //allocate an array

T* newelements=alloc.allocate(newcapacity);
or
T* newelements=static_cast&lt;T*&gt;(operator new [] (capacity * sizeof(T)));

Operator delete deallocates memory.
void operator delete(void*); // free an object
void operator delete[](void*); // free an array allocated through operator new[]

alloc.deallocate(front,end-front); // argument is size/count
operator delete[](front); // argument is array pointer
</pre>
Operator new and Operator delete are analogous to allocate and does not involve in
constructing the free memory.

