<pre class="slidecontent">

A class can overload operator new and operator delete. In this fashion calling
expression new and delete simply calls operator new and operator delete. operator new
has to memory allocation and initialization and overloaded operator delete has to call
destructor explicitly and then freeing the memory.

Overloading one of operator new or operator delete is an error.  Must overload both or
none.

This scenario is used to have own memory manager where pool of memory is allocated
once and then free is just returning to the pool and allocating is taking from the
pool.

In case of overloading operator new, default new expression can be called through
scope resolution operator.

<pre class="code">Type *p=::new Type;
::delete p;
</pre>
