 <a name="chap15">&nbsp;<div class="slideheader" style="height:135px">
  <pre class="day">Day 5 Morning</pre>
  <pre class="topic">  15. RTTI</pre>
  <ul class="slidecontent">
   <li class="big"><a name="chap15_0">typeid operator</a></li>   <li class="sml"><pre>dynamic_cast operator
</pre></li>   <li class="sml"><pre>type_info class
</pre></li>   <li class="sml"><pre>dynamic_cast vs static_cast
</pre></li>   <li class="sml"><pre>reinterpret_cast</pre></li>
  </ul>
 </div></a>
<pre class="slidecontent">

- RTTI allows programs that uses pointer or references to base classes to retrieve the
actual derived types of the objects to which these pointers or references refer.
- It is provided through two operators
1. The typeid operator, which returns the actual type of the object referred to by a
pointer or a reference.
2. The dynamic_cast operator, which safely converts from a pointer or reference to a
base type to a pointer or reference to a derived type.

- RTTI is computes at run time for classes which has virtual functions otherwise it
compute at compile time.

- typeid operator
 - Scenario
  - If two objects needs to be compared for equality then what can be solution.
  - provide overloaded function like following

<pre class="code">bool operator==(const Base&amp;, const Base&amp;);
bool operator==(const Derived&amp;, const Derived&amp;);
bool operator==(const Derived&amp;, const Base&amp;);
bool operator==(const Base&amp;, const Derived&amp;);
</pre>
This list can grow exponentially if derived classes are more
 - Other solution can be to have equal virtual function and let derived class override
it have have custom implementation. Problem with virtual equal function is that all
derived class must have Base pointer or reference in the function parameter. This let
to compare only Base class attributes.

 - The other solution is to have a class provided by the compiler which actually
fetches the information regarding the object's class. This is type_info class. typeid
operator would return object of type_Info class.

</pre> &nbsp;<div class="slideheader" style="height:135px">
  <pre class="day">Day 5 Morning</pre>
  <pre class="topic">  15. RTTI</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>typeid operator
