</pre></li>   <li class="sml"><pre>dynamic_cast vs static_cast
</pre></li>   <li class="sml"><pre>reinterpret_cast</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

- dynamic_cast
<pre class="code">struct A{};
struct B{};
struct C:A,B{}

                                          vtble
A*,C*  ----&gt;   +-----------+          +-----------+
               |   vptr    | --------&gt;|           | 
               +-----------+
               |A attribute|
               +-----------+
               |C attribute|
B* ------&gt;     +-----------+---------&gt;+-----------+
               |   vptr    |          |  thunk    |
               +-----------+          +-----------+
               |B attribute|
               +-----------+

B* b=new C;
C* c=dynamic_cast&lt;C*&gt;(b); // ok
C* c=static_cast&lt;C*&gt;(b);// error
</pre>                      
- Dynamic casts are needed when we have a reference or pointer to a base class but
need to perform operations from the derived class that are not part of the base class.
- To get derived behaviour of a pointer to base is to provide a virtual function and
get it implemented in derived class.
  
<pre class="code">if (Derived *derivedPtr = dynamic_cast&lt;Derived*&gt;(baseptr) ) {
</pre></pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main15" class="pn">p92</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
<pre class="code">} else {
}
</pre>or
<pre class="code">void f(const Base &amp;b) {
try {
const Derived &amp;d=dynamic_cast&lt;const Derived&amp;&gt;(b);
} catch (bad_cast) { // throws bad_cast
}
}
</pre>
</pre> &nbsp;<div class="slideheader" style="height:135px">
