<pre class="slidecontent">

- type_info class provides following operation
t1 == t2 Returns true if the two type_info objects t1 and t2 refer to the same type;
false otherwise.

t1 != t2 Returns true fi the two type_info objects t1 and t2 refer to different types;
false otherwise

t.name() Returns a c-style character string that is printable version of the type
name. Type names are generated in a system-dependent way.

t1.before(t2) Returns a bool that indicates whether t1 comes before t2.

The ordering imposed by before is compiler-dependent.

<pre class="code">Base *bp;
Derived *dp;
if(typeid(*bp) == typeid(*dp)) {
}
if(typeid(*bp) == typeid(Derived)) {
}

if pointer type is used then RTTI resolves at compile time
if (typeid(bp) == typeid(Derived)) { // never equal
}
</pre>
- If value of pointer p is 0, then typeid(*p) throws a bad_type exception provided p
has virtual functions.
- Combining typeid and dynamic_cast

<pre class="code">class Base {
friend bool operator==(const Base&amp;, const Base&amp;);
public:
protected:
virtual bool equal(const Base&amp;, const Base&amp;);
};
class Derived:public Base {
friend bool operator ==(const Base&amp;, const Base&amp;);
public:
private:
bool equal(const Base&amp;) const;
};
bool operator==(const Base &amp;lhs, const Base &amp;rhs) {
return typeid(lhs) == typeid(rhs) &amp;&amp; lhs.equal(rhs);
}

bool Derived::equal(const Base &amp;rhs) const {
if(const Derived *dp=dynamic_cast&lt;const Derived*&gt;(&amp;rhs) {
//do more stuff
} else
return false;
}
bool Base::equal(const Base &amp;rhs) const {
//do some base comparision of attributes
}
</pre>
