</pre></li>   <li class="sml"><pre>dynamic_cast vs static_cast
</pre></li>   <li class="big"><a name="chap15_4">reinterpret_cast</a></li>
  </ul>
 </div>
<pre class="slidecontent">
reinterpret_cast is used in low level conversions. Little or Big endian can be known
through reinterpret_cast

<pre class="code">unsigned int i=1;                            
--------                         --------
| 0x00 |                         | 0x10 |
--------                         --------
| 0x00 |                         | 0x00 |
--------                         --------
| 0x00 |                         | 0x00 |
--------                         --------
| 0x01 | &lt; -- little endian      | 0x00 |   &lt; -- big endian
--------                         --------

#include &lt;iostream&gt;
#include &lt;string&gt;
using namespace std;
int main(){
unsigned int i=1;
char *b=reinterpret_cast&lt;char*&gt;(&amp;i); // most of the machine
                         // char* represented in little endian
if(b[0])
cout&lt;&lt;"little endian";
else
cout&lt;&lt;"big endian";
return 0;
}
</pre>
</pre><pre class="ftr">&copy www.minhinc.com</pre><a href="#main15" class="pn">p94</a>
</div>
