<pre class="slidecontent">

C++11 is the ISO C++ standard ratified in 2011. The previous standard is often
referred to as C++98 or C++03; the differences between C++98 and C++03 are so few and
so technical that they ought not concern users.

</pre> &nbsp;<div class="slideheader" style="height:165px">
  <pre class="day">Day 5 Morning</pre>
  <pre class="topic">  16. Modern C++ Quick Tour</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>C++11 Intro
</pre></li>   <li class="big"><a name="chap16_1">Explicit Virtual Overrides</a></li>   <li class="sml"><pre>Uniform Initialization
</pre></li>   <li class="sml"><pre>Constructors
</pre></li>   <li class="sml"><pre>Type Interface
</pre></li>   <li class="sml"><pre> Range based for loop
</pre></li>   <li class="sml"><pre>Lambdas
</pre></li>   <li class="sml"><pre>Functional programming</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

No special keyword or annotation is needed for a function in a derived class to
override a function in a base class. For example:
<pre class="code">struct B {
virtual void f();
virtual void g() const;
virtual void h(char);
void k();       // not virtual
};

struct D : B {
void f();       // overrides B::f()
void g();       // doesn't override B::g() (wrong type)
virtual void h(char);   // overrides B::h()
void k();       // doesn't override B::k() (B::k() is not
virtual)
};
</pre>
This can cause confusion (what did the programmer mean?), and problems
if a compiler doesn't warn against suspicious code. For example,
* Did the programmer mean to override B::g()? (almost certainly yes)
* Did the programming mean to override B::h(char)? (probably not because of the
redundant explicit virtual).
* Did the programmer mean to override B::k()? (probably, but that's not possible).

To allow the programmer to be more explicit about overriding, we now have the
"contextual keyword" override:

<pre class="code">struct D : B {
void f() override;      // OK: overrides B::f()
void g() override;      // error: wrong type
virtual void h(char);   // overrides B::h(); likely warning
void k() override;      // error: B::k() is not virtual
};
</pre>
A declaration marked override is only valid if there is a function to override.
Override is only a contextual keyword, so you can still use it as an identifier:
<pre class="code">int override = 7;       // not recommended
</pre>
Override controls: final
Sometimes, a programmer wants to prevent a virtual function from being overridden.
This can be achieved by adding the specifier final. For example:

<pre class="code">struct B {
virtual void f() const final;   // do not override
virtual void g();
};
struct D : B {
void f() const;         // error: D::f attempts to override final B::f
void g();               // OK
};
</pre>
Final can be added for internal purpose and external user should not override it.

</pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main16" class="pn">p95</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
final is only a contextual keyword, so you can still use it as an identifier:
<pre class="code">int final = 7;  // not recommended
</pre>
</pre> &nbsp;<div class="slideheader" style="height:165px">
