</pre></li>   <li class="big"><a name="chap16_2">Uniform Initialization</a></li>   <li class="sml"><pre>Constructors
</pre></li>   <li class="sml"><pre>Type Interface
</pre></li>   <li class="sml"><pre> Range based for loop
</pre></li>   <li class="sml"><pre>Lambdas
</pre></li>   <li class="sml"><pre>Functional programming</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

C++ offers several ways of initializing an object depending on its type and the
initialization context.

<pre class="code">string a[] = { "foo", " bar" }; // ok: initialize array variable
vector&lt;string&gt; v = { "foo", " bar" }; // error: initializer list for non-aggregate
vector
void f(string a[]);
f( { "foo", " bar" } ); // syntax error: block as argument
</pre>
and
<pre class="code">int a = 2;              // ''assignment style''
int aa[] = { 2, 3 };    // assignment style with list
complex z(1,2);         // ''functional style'' initialization
x = Ptr(y);             // ''functional style'' for conversion/cast/construction
</pre>
and
<pre class="code">int a(1);       // variable definition
int b();        // function declaration
int b(foo);     // variable definition or function declaration
</pre>
It can be hard to remember the rules for initialization and to choose the best way.

The C++11 solution is to allow {}-initializer lists for all initialization:
<pre class="code">X x1 = X{1,2};
X x2 = {1,2};   // the = is optional
X x3{1,2};
X* p = new X{1,2};

struct D : X {
D(int x, int y) :X{x,y} { /* ... */ };
};

struct S {
int a[3];
S(int x, int y, int z) :a{x,y,z} { /* ... */ }; // solution to old problem
};
</pre>
Importantly, X{a} constructs the same value in every context, so that
{}-initialization gives the same result in all places where it is legal.
For example:
<pre class="code">X x{a};
X* p = new X{a};
z = X{a};         // use as cast
f({a});           // function argument (of type X)
return {a};       // function return value (function returning X)
</pre>
</pre> &nbsp;<div class="slideheader" style="height:165px">
  <pre class="day">Day 5 Morning</pre>
  <pre class="topic">  16. Modern C++ Quick Tour</pre>
  <ul class="slidecontent">
