</pre></li>   <li class="sml"><pre>Explicit Virtual Overrides
</pre></li>   <li class="sml"><pre>Uniform Initialization
</pre></li>   <li class="big"><a name="chap16_3">Constructors</a></li>   <li class="sml"><pre>Type Interface
</pre></li>   <li class="sml"><pre> Range based for loop
</pre></li>   <li class="sml"><pre>Lambdas
</pre></li>   <li class="sml"><pre>Functional programming</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

Inherited constructors
<pre class="code">struct B {
void f(double);
};
struct D : B {
void f(int);
};
B b;   b.f(4.5);        // fine
D d;   d.f(4.5);        // surprise: calls f(int) with argument 4
</pre>
In C++98, we can "lift" a set of overloaded functions from a base class into a derived
</pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main16" class="pn">p96</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
class:
<pre class="code">struct B {
void f(double);
};
struct D : B {
using B::f;     // bring all f()s from B into scope
void f(int);    // add a new f()
};

B b;   b.f(4.5);        // fine
D d;   d.f(4.5);        // fine: calls D::f(double) which is B::f(double)

class Derived : public Base {
public:
using Base::f;    // lift Base's f into Derived's scope -- works in C++98
void f(char);     // provide a new f
void f(int);      // prefer this f to Base::f(int)

using Base::Base; // lift Base constructors Derived's scope -- C++11 only
Derived(char);    // provide a new constructor
Derived(int);     // prefer this constructor to Base::Base(int)
// ...
};
</pre>
If you so choose, you can still shoot yourself in the foot by inheriting constructors
in a derived class in which you define new member variables needing initialization:

<pre class="code">struct B1 {
B1(int) { }
};
struct D1 : B1 {
using B1::B1; // implicitly declares D1(int)
int x;
};
void test()
{
D1 d(6);        // Oops: d.x is not initialized
D1 e;           // error: D1 has no default constructor
}
</pre>
You might remove the bullet from your foot by using a member-initializer:
<pre class="code">struct D1 : B1 {
using B1::B1;   // implicitly declares D1(int)
int x{0};       // note: x is initialized
};
void test()
{
D1 d(6);        // d.x is zero
}
</pre>
</pre> &nbsp;<div class="slideheader" style="height:165px">
  <pre class="day">Day 5 Morning</pre>
  <pre class="topic">  16. Modern C++ Quick Tour</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>C++11 Intro
</pre></li>   <li class="sml"><pre>Explicit Virtual Overrides
</pre></li>   <li class="sml"><pre>Uniform Initialization
</pre></li>   <li class="sml"><pre>Constructors
</pre></li>   <li class="big"><a name="chap16_4">Type Interface</a></li>   <li class="sml"><pre> Range based for loop
</pre></li>   <li class="sml"><pre>Lambdas
</pre></li>   <li class="sml"><pre>Functional programming</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

Consider:
<pre class="code">template&lt;class T, class U&gt;
  ??? mul(T x, U y)
{
return x*y;
}
</pre>
What can we write as the return type? It's "the type of x*y", of course, but how can
we say that? First idea, use decltype:
<pre class="code">template&lt;class T, class U&gt;
decltype(x*y) mul(T x, U y) // scope problem!
{
return x*y;
}
</pre>
The solution is put the return type where it belongs, after the arguments:
<pre class="code">template&lt;class T, class U&gt;
auto mul(T x, U y) -&gt; decltype(x*y)
{
return x*y;
}
</pre>
We use the notation auto to mean "return type to be deduced or specified later."
</pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main16" class="pn">p97</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">

The suffix syntax is not primarily about templates and type deduction,
it is really about scope.
<pre class="code">struct List {
struct Link { /* ... */ };
Link* erase(Link* p);   // remove p and return the link before p
// ...
};
List::Link* List::erase(Link* p) { /* ... */ }
</pre>
The first List:: is necessary only because the scope of List isn't entered until the
second List::. Better:

<pre class="code">auto List::erase(Link* p) -&gt; Link* { /* ... */ }
</pre>
Now neither Link needs explicit qualification.

</pre> &nbsp;<div class="slideheader" style="height:165px">
  <pre class="day">Day 5 Morning</pre>
  <pre class="topic">  16. Modern C++ Quick Tour</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>C++11 Intro
</pre></li>   <li class="sml"><pre>Explicit Virtual Overrides
</pre></li>   <li class="sml"><pre>Uniform Initialization
</pre></li>   <li class="sml"><pre>Constructors
</pre></li>   <li class="sml"><pre>Type Interface
</pre></li>   <li class="big"><a name="chap16_5"> Range based for loop</a></li>   <li class="sml"><pre>Lambdas
</pre></li>   <li class="sml"><pre>Functional programming</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

A range for statement allows you to iterate through a "range", which is anything you
can iterate through like an STL-sequence defined by a begin() and end(). All standard
containers can be used as a range, as can a std::string, an initializer list, an
array, and anything for which you define begin() and end(), e.g. an istream. For  
example:

<pre class="code">void f(vector&lt;double&gt;&amp; v)
{
for (auto x : v) cout &lt;&lt; x &lt;&lt; '\n';
for (auto&amp; x : v) ++x;  // using a reference to allow us to change the value
}
</pre>

You can read that as "for all x in v" going through starting with v.begin() and
iterating to v.end(). Another example:
 
<pre class="code">for (const auto x : { 1,2,3,5,8,13,21,34 }) cout &lt;&lt; x &lt;&lt; '\n';
</pre>
The begin() (and end()) can be a member to be called x.begin() or a free-standing
function to be called begin(x). The member version takes precedence.
 
</pre> &nbsp;<div class="slideheader" style="height:165px">
  <pre class="day">Day 5 Morning</pre>
  <pre class="topic">  16. Modern C++ Quick Tour</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>C++11 Intro
</pre></li>   <li class="sml"><pre>Explicit Virtual Overrides
</pre></li>   <li class="sml"><pre>Uniform Initialization
</pre></li>   <li class="sml"><pre>Constructors
</pre></li>   <li class="sml"><pre>Type Interface
</pre></li>   <li class="sml"><pre> Range based for loop
</pre></li>   <li class="big"><a name="chap16_6">Lambdas</a></li>   <li class="sml"><pre>Functional programming</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

A lambda expression is a mechanism for specifying a function object. The primary use
for a lambda is to specify a simple action to be performed by some function. For
example:

<pre class="code">vector&lt;int&gt; v = {50, -10, 20, -30};
std::sort(v.begin(), v.end());  // the default sort
// now v should be { -30, -10, 20, 50 }
// sort by absolute value:
std::sort(v.begin(), v.end(), [](int a, int b) { return abs(a)&lt;abs(b); });
// now v should be { -10, 20, -30, 50 }

A lambda expression can access local variables in the scope in which it is used. For
example:
void f(vector&lt;Record&gt;&amp; v)
{
vector&lt;int&gt; indices(v.size());
int count = 0;
generate(indices.begin(),indices.end(),[&amp;count](){
return count++; 
</pre></pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main16" class="pn">p98</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
<pre class="code">});

// sort indices in the order determined by the name field of the records:
std::sort(indices.begin(), indices.end(), [&amp;](int a, int b) {
return v[a].name&lt;v[b].name; });
// ...
}
</pre>

We could have said that we wanted to "capture" only v, we could have said so: [&amp;v].
Had we wanted to pass v by value, we could have said so: [=v]. Capture nothing is [],
capture all by references is[&amp;], and capture
all by value is [=].

If an action is neither common nor simple, use a named function object or function
<pre class="code">void f(vector&lt;Record&gt;&amp; v)
{
vector&lt;int&gt; indices(v.size());
int count = 0;
generate(indices.begin(),indices.end(),[&amp;](){ return ++count; });

struct Cmp_names {
const vector&lt;Record&gt;&amp; vr;
Cmp_names(const vector&lt;Record&gt;&amp; r) :vr(r) { }
bool operator()(int a, int b) const { return vr[a].name&lt;vr[b].name; }
};

// sort indices in the order determined by the name field of the records:
std::sort(indices.begin(), indices.end(), Cmp_names(v));
// ...
}
</pre>
