 <a name="chap17">&nbsp;<div class="slideheader" style="height:115px">
  <pre class="day">Day 5 Afternoon</pre>
  <pre class="topic">  17. Pointer to class member</pre>
  <ul class="slidecontent">
   <li class="big"><a name="chap17_0">Declaring pointer to class member</a></li>   <li class="sml"><pre> Using pointer to class member
</pre></li>   <li class="sml"><pre>Command design pattern</pre></li>
  </ul>
 </div></a>
<pre class="slidecontent">

Pointer to class member (method or attributes) are important in the sense it can be
used as generic type at many places including function argument types.

Pointer to member is applicable only to non-static members.

Attribute has grammar like
<pre class="code">&lt;attribute type&gt; &lt;classname&gt;::*
</pre>
Methods has grammar like
<pre class="code">&lt;return type&gt; (&lt;classname&gt;::*)(argments)

class filebuffer{
public:
typedef std::string::size_type index;
char get() const;
char get(index offset) const;
private:
std::string content;
index offsetpos;
index length;
};

string filebuffer::*pfb_conent=&amp;filebuffer::content;
filebuffer::index filebuffer::*pfb_offset=&amp;filebuffer::offsetpos;
Char (filebuffer::*pfb_get)(filebuffer::index) const=&amp;filebuffer::get;


Typedef
typedef char (filebuf::*action)(filebuff::index) const;
filebuf&amp; func(const filebuf&amp;,action=&amp;filebuf::get);

func(filebuf());
func(filebuf(),&amp;filebuf::get);
action get=&amp;filebuf::get;
func(filebuf(),get);
</pre>
</pre> &nbsp;<div class="slideheader" style="height:115px">
  <pre class="day">Day 5 Afternoon</pre>
  <pre class="topic">  17. Pointer to class member</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>Declaring pointer to class member
</pre></li>   <li class="big"><a name="chap17_1"> Using pointer to class member</a></li>   <li class="sml"><pre>Command design pattern</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

The pointer-to-member dereference operator (.*) fetches the member from an object or
reference.

The pointer-to-member arrow operator (-&gt;*) fetches the member through a pointer to an
object.

Calling methods

<pre class="code">char (filebuffer::*pfbget)() const = &amp;filebuffer::get;
filebuffer filebuf;
char c1=filebuf.get(); // normal call
char c2=(filebur::.*pfbget)(); // through pointer class member

filebuffer *pfilebuf=&amp;filebuf;
char c3=(filebuf::-&gt;*pfbget)();
</pre>
Calling data member

<pre class="code">filebuf::index filebuf::*pindex=&amp;filebuff::offsetpos;
filebuf::index pos1=filebuf.offsetpos;
filebuf::index pos2=filebuf.*pindex;
filebuf::index pos3=pfilebuf-&gt;*pindex;
</pre>
</pre><pre class="ftr">&copy www.minhinc.com</pre><a href="#main17" class="pn">p100</a>
</div> <div class="pg" style="margin-top:20px;height:1395px">
 &nbsp;<div class="slideheader" style="height:115px">
  <pre class="day">Day 5 Afternoon</pre>
  <pre class="topic">  17. Pointer to class member</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>Declaring pointer to class member
</pre></li>   <li class="sml"><pre> Using pointer to class member
</pre></li>   <li class="big"><a name="chap17_2">Command design pattern</a></li>
  </ul>
 </div>
<pre class="slidecontent">

<pre class="code">$cat main.cpp
#include &lt;iostream&gt;
struct robot{
void left(int dp){std::cout&lt;&lt;"robot::moved left, distance "&lt;&lt;dp&lt;&lt;std::endl;}
void right(int dp){std::cout&lt;&lt;"robot::moved right, distance "&lt;&lt;dp&lt;&lt;std::endl;}
void front(int dp){std::cout&lt;&lt;"robot::move front distance "&lt;&lt;dp&lt;&lt;std::endl;}
void back(int dp){std::cout&lt;&lt;"robot::moved back distance "&lt;&lt;dp&lt;&lt;std::endl;}
};

struct command{
typedef void (robot::*actiontype)(int);
command(robot *rp,actiontype actp,int dp);
void move();
robot *rbt;
int dist;
actiontype act;
};
command::command(robot *rp,actiontype actp,int dp){
rbt=rp;
act=actp;
dist=dp;
}

void command::move(){
(rbt-&gt;*act)(dist);
}
int main(int argc, char *argv[]){
robot *rbt=new robot;
int i=0;
command cmd[2]={command(rbt,&amp;robot::left,4),command(rbt,&amp;robot::right,6)};
for(i=0;i&lt;2;i++)
cmd[i].move();
return 0;
}
</pre>
$ g++ -o command main.cpp
$ ./command 
<pre class="code">robot::moved left, distance 4
robot::moved right, distance 6
</pre>
