 <a name="chap18">&nbsp;<div class="slideheader" style="height:115px">
  <pre class="day">Day 5 Afternoon</pre>
  <pre class="topic">  18. Nested class and volatile operator</pre>
  <ul class="slidecontent">
   <li class="big"><a name="chap18_0">Defining nested class members</a></li>   <li class="sml"><pre>Defining nested class outside the enclosing class
</pre></li>   <li class="sml"><pre>Volatile qualifier</pre></li>
  </ul>
 </div></a>
<pre class="slidecontent">

Nested Classes
A class defined within another class is a nested class/type.
A nested class is visible only in enclosing class scope and not in scope where
enclosing close is defined.

Enclosing class and nested class need to access each others member as independent
classes. So nested class just scopes a class other wise there is other different when
it is two different classes.

<pre class="code">template&lt;class type&gt;class queue{
private:
struct queueitem{
queueitem(const type &amp;);
type item;
aueueitem *next;
};
aueueitem *head;
aueueitem *tail;
};

template&lt;class type&gt;
queue&lt;type&gt;::queueitem::queueitem(const type &amp;t):
                                item(t),next(0){}
</pre>
</pre> &nbsp;<div class="slideheader" style="height:115px">
  <pre class="day">Day 5 Afternoon</pre>
  <pre class="topic">  18. Nested class and volatile operator</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>Defining nested class members
</pre></li>   <li class="big"><a name="chap18_1">Defining nested class outside the enclosing class</a></li>   <li class="sml"><pre>Volatile qualifier</pre></li>
  </ul>
 </div>
<pre class="slidecontent">

In case user of enclosing class need see the implementation of the nested class.
Forward declare the nested class.

<pre class="code">template &lt;class type&gt; class queue{
private:
struct queueitem;
queueitem *head;
queueitem *tail;
};

template &lt;class type&gt;
struct queue&lt;type&gt;::queueitem{
queueitem(const type &amp;t):item(t)&lt;next(0){}
type item;
queueitem *next;
};
</pre>
</pre> &nbsp;<div class="slideheader" style="height:115px">
  <pre class="day">Day 5 Afternoon</pre>
  <pre class="topic">  18. Nested class and volatile operator</pre>
  <ul class="slidecontent">
   <li class="sml"><pre>Defining nested class members
</pre></li>   <li class="sml"><pre>Defining nested class outside the enclosing class
</pre></li>   <li class="big"><a name="chap18_2">Volatile qualifier</a></li>
  </ul>
 </div>
<pre class="slidecontent">

Some variables value depends on hardware and can change externally. This makes value
not to be optimized by the compiler. Volatile operator puts tag on variable so that
compiler would not optimize the variable.

For example, for a machine with memory-mapped input/output, a pointer to a device
register might be declared as a pointer to volatile, in order to prevent the compiler
from removing apparently redundant references through the pointer.  Except that it
should diagnose explicit attempts to change const objects, a compiler may ignore these
qualifiers.


Port
<pre class="code">---------------------------------------------
| control register |     |  data register   |
---------------------------------------------
</pre></pre>
<pre class="ftr">&copy www.minhinc.com</pre><a href="#main18" class="pn">p102</a>
</div>
<div class="pg" style="margin-top:20px;height:1395px">
<pre class="slidecontent">
<pre class="code">
typedef short int control;
typedef short int data;
#define ENABLE 0x40
#define READY 0x80
typedef struct port port;
struct port
{
control c;
data d;
};
typedef struct ioport ioport;
struct ioport
{
port in, out;
};

//Using the declarations above, assign one memory mapped address to it
ioport *const pio = (ioport *)0xFF70;
// check if control register ready bit is ready for data to be written
while (pio-&gt;out.c &amp; READY == 0)
;
//write carriage return
pio-&gt;out.d = '\r';
while (pio-&gt;out.c &amp; READY == 0)
;
pio-&gt;out.d = '\n';
//.Compiler start doing the optimization in following ways.
//Optimization

if (pio-&gt;out.c &amp; READY == 0)
for (;;)
;
pio-&gt;out.d = '\r';
if (pio-&gt;out.c &amp; READY == 0)
for (;;)
;
pio-&gt;out.d = '\n';
Optimization
if (pio-&gt;out.c &amp; READY == 0)
for (;;)
;
pio-&gt;out.d = '\r';
pio-&gt;out.d = '\n';

//Further Optimization where '\r' is removed as redundant
if (pio-&gt;out.c &amp; READY == 0)
for (;;)
;
pio-&gt;out.d = '\n';
</pre>
Solution
<pre class="code">ioport volatile *const pio = (ioport *)0xFFA0;
</pre>
In C+= volatile operator is similar to const where const and non-const variable can be
assigned to a const variable. Volatile &lt;--- const &lt;--- normal , a non volatile
variable can not be assigned to volatile

<pre class="code">volatile int v;
int *ip=&amp;v; // error
volatile int *ip=&amp;v; //ok
</pre>
Only volatile member functions may be called on volatile objects.

Synthesized copy constructor and assignment operator does not include volatile in the
argument type. This makes volatile object not be copied. In case of volatile objects
copy constructor and synthesized operator need to be declared explicitly.

<pre class="code">Class A{
Public:
A(const volatile A&amp;); // similar to const, copy from volatile object
A&amp; operator=(volatile const A&amp;); // copy from volatile object
A&amp; operator=(volatile const A&amp;) volatile; //copy from volatile to volatile object
};
</pre>
